function refreshAdvancedFilters(){const categorySelect=$('#txCategoryFilter'),accountSelect=$('#txAccountFilter'),monthSelect=$('#txMonthFilter');if(!categorySelect||!accountSelect||!monthSelect)return;const setOptions=(select,items,selected,label)=>{select.innerHTML=`<option value="">${label}</option>${items.map(item=>`<option value="${esc(item.value)}" ${item.value===selected?'selected':''}>${esc(item.label)}</option>`).join('')}`};setOptions(categorySelect,[...new Set(state.transactions.map(transaction=>transaction.category||'Diğer'))].sort((a,b)=>a.localeCompare(b,'tr')).map(value=>({value,label:value})),txCategory,'Tüm kategoriler');setOptions(accountSelect,state.accounts.filter(account=>!account.archivedAt).map(account=>({value:account.id,label:account.name})),txAccount,'Tüm hesaplar');setOptions(monthSelect,[...new Set(state.transactions.map(transaction=>transaction.date.slice(0,7)))].sort().reverse().map(value=>({value,label:new Date(`${value}-01T12:00`).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})})),txMonth,'Tüm aylar')}
