async function marketFetch(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{return await fetch(url,{...options,signal:controller.signal})}catch(error){if(error.name==='AbortError')throw new Error('Fiyat sağlayıcısı zamanında yanıt vermedi.');throw error}finally{clearTimeout(timer)}}
async function refreshInvestment(asset){let priceMinor;if(asset.type==='gold'){const response=await marketFetch('https://xaus.com/api/v1/spot?currency=TRY&unit=gram',{referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Altın fiyatı alınamadı.');const data=await response.json();priceMinor=FinanceCore.marketPriceMinor(data.xau?.price)}else if(asset.type==='currency'){const response=await marketFetch(`https://api.frankfurter.dev/v1/latest?base=${encodeURIComponent(asset.symbol)}&symbols=TRY`,{referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Döviz kuru alınamadı.');const data=await response.json();priceMinor=FinanceCore.marketPriceMinor(data.rates?.TRY)}else{const source=`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(asset.symbol)}?range=1d&interval=1d`,response=await marketFetch(`https://proxy.cors.dev/${source}`,{credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Piyasa verisi alınamadı.');const data=await response.json(),meta=data.chart?.result?.[0]?.meta,rawPrice=meta?.regularMarketPrice;if(!Number.isFinite(rawPrice))throw new Error('Güncel fiyat bulunamadı.');let quoteMinor=FinanceCore.marketPriceMinor(rawPrice);if(meta.currency&&meta.currency!=='TRY'){const fx=await marketFetch(`https://api.frankfurter.dev/v1/latest?base=${encodeURIComponent(meta.currency)}&symbols=TRY`,{referrerPolicy:'no-referrer'});if(!fx.ok)throw new Error('Döviz dönüşümü alınamadı.');const rateMinor=FinanceCore.marketPriceMinor((await fx.json()).rates?.TRY);quoteMinor=Number((BigInt(quoteMinor)*BigInt(rateMinor))/100n)}priceMinor=quoteMinor}const valuation={id:id(),assetId:asset.id,priceMinor,date:dateISO(),fetchedAt:new Date().toISOString(),source:asset.type==='gold'?'xaus.com':asset.type==='currency'?'frankfurter.dev':'Yahoo Finance'};await put('assetValuations',valuation);await put('investmentAssets',{...asset,currentPriceMinor:priceMinor,currentPriceDate:dateISO(),updatedAt:dateISO()})}
async function refreshInvestments(){if(!navigator.onLine){toast('Fiyat güncellemesi için internet bağlantısı gerekli.');return}if(!state.investments.length){toast('Önce bir yatırım ekleyin.');return}let completed=0;for(const asset of state.investments){try{await refreshInvestment(asset);completed++}catch(error){console.warn(error)}}await load();toast(completed?`${completed} yatırımın fiyatı güncellendi`:'Fiyat alınamadı; sembolleri kontrol edin.')}
