function openDB(){return new Promise((ok,no)=>{const r=indexedDB.open(DB,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result,tx=r.transaction;if(!d.objectStoreNames.contains('accounts'))d.createObjectStore('accounts',{keyPath:'id'});if(!d.objectStoreNames.contains('transactions'))d.createObjectStore('transactions',{keyPath:'id'});const transactions=tx.objectStore('transactions');if(!transactions.indexNames.contains('byDate'))transactions.createIndex('byDate','date');for(const name of ['profiles','categories','subcategories','attachments','budgets','schedules','auditRecords','appSettings','cardProfiles','cardPurchases','cardStatements','recurringTransactions','savingsGoals','goalContributions','debts','debtSettlements','loans','investmentAssets','assetValuations','investmentTransactions','forecastScenarios'])if(!d.objectStoreNames.contains(name))d.createObjectStore(name,{keyPath:'id'});};r.onsuccess=()=>{db=r.result;ok()};r.onerror=()=>no(r.error)})}
function all(store){return new Promise((ok,no)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}
function put(store,item){return new Promise((ok,no)=>{const r=db.transaction(store,'readwrite').objectStore(store).put(item);r.onsuccess=ok;r.onerror=()=>no(r.error)})}
