function renderCategories(txs,total){let grouped={};txs.filter(t=>txType(t)==='expense').forEach(t=>{let k=t.category||'Diğer';grouped[k]=(grouped[k]||0)+entryAmount(t.postings.find(p=>p.accountId==='expense')||{})});let icons={Market:'🛒',Yemek:'☕',Ulaşım:'◉',Fatura:'⌁',Eğlence:'✦',Sağlık:'＋',Diğer:'·'};let rows=Object.entries(grouped).sort((a,b)=>b[1]-a[1]).slice(0,3);let empty='<div class="catRow"><span class="catIcon">✦</span><div><span class="catName">Henüz harcama yok</span><div class="catTrack"><i style="width:0"></i></div></div><span class="catValue">₺0</span></div>';$('#spendingCategories').innerHTML=rows.length?rows.map(([n,v])=>`<div class="catRow"><span class="catIcon">${icons[n]||'·'}</span><div><span class="catName">${esc(n)}</span><div class="catTrack"><i style="width:${total?v/total*100:0}%"></i></div></div><span class="catValue">${money(v)}</span></div>`).join(''):empty}
function recurringDueMinor(monthKey){let total=0;for(const recurring of state.recurring.filter(r=>r.active!==false)){let due=recurring.nextDueDate;for(let guard=0;guard<120&&due.slice(0,7)<=monthKey;guard++){if(due.slice(0,7)===monthKey)total+=recurring.direction==='income'?-recurring.amountMinor:recurring.amountMinor;due=nextRecurringDate(recurring,due)}}for(const debt of [...state.debts,...state.loans].filter(d=>d.active!==false)){for(let payment=0;payment<Math.min(600,Number(debt.remainingInstallments)||0);payment++){let due=FinanceCore.addMonths(debt.nextDueDate,payment);if(due.slice(0,7)===monthKey)total+=debt.direction==='incoming'?-debt.monthlyPaymentMinor:debt.monthlyPaymentMinor;if(due.slice(0,7)>monthKey)break}}return total}
function calendarEvents(month){const events=[],add=(date,title,detail,status,action,key)=>events.push({date,title,detail,status,action,key});for(const transaction of state.transactions.filter(item=>item.date.startsWith(month))){const expense=txType(transaction)==='expense',income=txType(transaction)==='income',amount=Math.abs(entryAmount(transaction.postings.find(posting=>posting.accountId==='expense'||posting.accountId==='income')||transaction.postings[0]||{}));add(transaction.date,transaction.note||'Hareket',`${income?'Gelir':expense?'Gider':'Transfer'} • ${money(amount)}`,transaction.planned?'Planlandı':'İşlendi','transaction',transaction.id)}for(const recurring of state.recurring.filter(item=>item.active!==false)){let due=recurring.nextDueDate;for(let guard=0;guard<120&&due.slice(0,7)<=month;guard++){if(due.slice(0,7)===month)add(due,recurring.name,`Düzenli ödeme • ${money(recurring.amountMinor/100)}`,'Bekliyor','recurring',recurring.id);due=nextRecurringDate(recurring,due)}}for(const debt of [...state.debts,...state.loans].filter(item=>item.active!==false)){for(let count=0;count<Math.min(600,Number(debt.remainingInstallments)||0);count++){const due=FinanceCore.addMonths(debt.nextDueDate,count);if(due.slice(0,7)===month)add(due,debt.name,`${debt.direction==='incoming'?'Tahsilat':'Borç / kredi'} • ${money(debt.monthlyPaymentMinor/100)}`,'Bekliyor','debt',debt.id);if(due.slice(0,7)>month)break}}for(const card of state.accounts.filter(account=>account.type==='card'&&account.closingDay)){const cycle=FinanceCore.cardCycleWithDueOffset(`${month}-01`,card.closingDay,10,Boolean(card.closingDayPurchasesNext));if(cycle.closingDate.startsWith(month))add(cycle.closingDate,card.name,'Ekstre kesim günü','Bilgi','account',card.id);if(cycle.dueDate.startsWith(month))add(cycle.dueDate,card.name,'Kart son ödeme tarihi','Bekliyor','account',card.id)}return events.sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title,'tr'))}
function renderCalendar(){const list=$('#calendarList'),title=$('#calendarTitle');if(!list||!title)return;const [year,month]=calendarMonth.split('-').map(Number);title.textContent=new Date(year,month-1,1).toLocaleDateString('tr-TR',{month:'long',year:'numeric'});const events=calendarEvents(calendarMonth);list.innerHTML=events.length?events.map(event=>`<button type="button" class="budget-row" ${event.action==='transaction'?`data-edit-id="${event.key}"`:event.action==='recurring'?`data-recurring-edit="${event.key}"`:event.action==='debt'?`data-debt-settle="${event.key}"`:`data-account-id="${event.key}"`}><b><span>${fmtDate(event.date)} • ${esc(event.title)}</span><span>${esc(event.status)}</span></b><small>${esc(event.detail)}</small></button>`).join(''):'<div class="budget-row"><b>Bu ay için kayıt yok</b><small>Hareketler, düzenli ödemeler, borçlar ve kart tarihleri burada görünür.</small></div>'}
function renderForecast(){const cashAccounts=state.accounts.filter(a=>isLiquidAccount(a)&&!a.archivedAt&&a.includeInTotals!==false);let html='',base=cashAccounts.reduce((n,a)=>n+accountBalance(a),0),max=1;let rows=[];for(let i=0;i<12;i++){let monthStart=FinanceCore.addMonths(dateISO().slice(0,8)+'01',i),key=monthStart.slice(0,7);let delta=state.transactions.filter(t=>t.planned&&t.date>dateISO()&&t.date.startsWith(key)).reduce((x,t)=>x+t.postings.filter(p=>cashAccounts.some(a=>a.id===p.accountId)).reduce((y,p)=>y+entryAmount(p),0),0)-recurringDueMinor(key)/100;base+=delta;rows.push({monthStart,base});max=Math.max(max,...rows.map(x=>Math.abs(x.base)))}for(const r of rows){let [y,m]=r.monthStart.split('-');html+=`<div class="month"><span>${new Date(Number(y),Number(m)-1,1).toLocaleDateString('tr-TR',{month:'short',year:'2-digit'})}</span><div class="bar"><i style="width:${Math.max(3,Math.abs(r.base)/max*100)}%"></i></div><b>${money(r.base)}</b></div>`}$('#forecast').innerHTML=html}
