deleteInvestment=async function(assetId){const asset=state.investments.find(item=>item.id===assetId);if(!asset)return;const history=state.investmentTransactions.filter(item=>item.assetId===assetId);if(!confirm(`${asset.name} yatırımı${history.length?` ve ${history.length} alım-satım kaydı`:''} silinsin mi? Bu işlem geri alınamaz.`))return;for(const valuation of await all('assetValuations'))if(valuation.assetId===assetId)await remove('assetValuations',valuation.id);for(const row of history)await remove('investmentTransactions',row.id);await remove('investmentAssets',assetId);await load();toast('Yatırım ve yerel hareket geçmişi silindi')};
