async function restoreV41(file){try{const envelope=JSON.parse(await file.text());if(envelope.format!=='cep-finans-backup'||!Number.isInteger(envelope.version)||envelope.version>4)throw new Error('Desteklenmeyen yedek.');const pass=prompt('Yedek parolası:');if(!pass)return;const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(envelope.iv)},await derive(pass,unb64(envelope.salt)),unb64(envelope.ciphertext)),data=JSON.parse(new TextDecoder().decode(plain));if(!Array.isArray(data.accounts)||!Array.isArray(data.transactions))throw new Error('Yedek içeriği geçersiz.');for(const storeName of BACKUP_STORES)if(!Array.isArray(data[storeName]))data[storeName]=[];for(const item of data.attachments)if(item.blob?.base64)item.blob=new Blob([largeUnb64(item.blob.base64)],{type:item.blob.type||item.type||'application/octet-stream'});const count=BACKUP_STORES.reduce((total,storeName)=>total+data[storeName].length,0);if(!confirm(`Bu işlem yedekteki ${count} kaydı geri yükler ve mevcut kayıtların yerini alır. Devam edilsin mi?`))return;await replaceCoreData(data);await load();toast('Yedek güvenle geri yüklendi')}catch(error){toast('Yedek açılamadı: parola veya dosya hatalı.')}$('restoreFile').value=''}
