const cepFinansTransactionMatches=transactionMatches;transactionMatches=function(transaction){if(!cepFinansTransactionMatches(transaction))return false;return !txTag||(transaction.tags||[]).some(tag=>tag.toLocaleLowerCase('tr-TR').includes(txTag.toLocaleLowerCase('tr-TR')))};
function transactionComparator(a,b){if(txSort==='dateAsc')return a.date.localeCompare(b.date);if(txSort==='amountDesc'||txSort==='amountAsc'){const amount=item=>Math.abs(entryAmount(item.postings.find(posting=>posting.accountId==='expense'||posting.accountId==='income')||item.postings[0]||{}));return txSort==='amountDesc'?amount(b)-amount(a):amount(a)-amount(b)}if(txSort==='note')return String(a.note||'').localeCompare(String(b.note||''),'tr');return b.date.localeCompare(a.date)}
