/* Düzenli kayıtlar: tüm takvim aralıkları, değişken tutar ve güvenli silme. */
const recurringFrequencyOptions=[['daily','Günlük'],['weekly','Haftalık'],['biweekly','İki haftada bir'],['monthly','Aylık'],['quarterly','3 aylık'],['semiannual','6 aylık'],['yearly','Yıllık']];
function recurringEditor(recurringId){const existing=recurringId?state.recurring.find(item=>item.id===recurringId):null,accounts=state.accounts.filter(account=>!account.archivedAt&&account.type!=='card');if(!accounts.length){toast('Önce aktif bir banka hesabı ekleyin.');return}const amount=existing?(existing.amountMinor/100).toFixed(2).replace('.',','):'',options=accounts.map(account=>`<option value="${account.id}" ${account.id===existing?.accountId?'selected':''}>${esc(account.name)}</option>`).join('');show(`<h2 class="formTitle">${existing?'Düzenli kaydı düzenle':'Düzenli kayıt ekle'}</h2><label class="field">Tür<select name="direction"><option value="expense" ${existing?.direction!=='income'?'selected':''}>Düzenli gider</option><option value="income" ${existing?.direction==='income'?'selected':''}>Düzenli gelir</option></select></label><label class="field">Ad<input required name="name" maxlength="80" value="${esc(existing?.name||'')}" placeholder="Örn. İnternet faturası"></label><label class="field">Varsayılan tutar (TL)<input required name="amount" type="text" inputmode="decimal" value="${amount}" placeholder="0,00"></label><label class="field">Tutar her vade değişebilir mi?<input name="variableAmount" type="checkbox" ${existing?.variableAmount?'checked':''}></label><label class="field">Kategori<select name="category">${[...new Set([...availableCategories(),existing?.category||'Diğer'])].map(name=>`<option ${name===(existing?.category||'Diğer')?'selected':''}>${esc(name)}</option>`).join('')}</select></label><label class="field">Hesap<select name="accountId">${options}</select></label><label class="field">Sıklık<select name="frequency">${recurringFrequencyOptions.map(([value,label])=>`<option value="${value}" ${value===(existing?.frequency||'monthly')?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Sonraki vade<input required name="nextDueDate" type="date" value="${existing?.nextDueDate||dateISO()}"></label><label class="field">Plan etkin mi?<input name="active" type="checkbox" ${existing?.active!==false?'checked':''}></label><div class="formActions"><button>Kaydet</button>${existing?`<button type="button" data-recurring-delete="${existing.id}">Sil</button>`:''}<button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const name=String(form.get('name')||'').trim(),amountMinor=FinanceCore.minor(form.get('amount'));if(!name||amountMinor<=0)throw new Error('Ad ve sıfırdan büyük tutar gerekli.');await put('recurringTransactions',{...(existing||{}),id:existing?.id||id(),schemaVersion:3,name,amountMinor,variableAmount:form.get('variableAmount')==='on',category:String(form.get('category')||'Diğer'),direction:form.get('direction'),accountId:form.get('accountId'),frequency:form.get('frequency'),nextDueDate:FinanceCore.date(form.get('nextDueDate')),active:form.get('active')==='on',postingPolicy:'manual',updatedAt:new Date().toISOString()});await load();toast('Düzenli kayıt kaydedildi')}catch(error){toast(error.message||'Düzenli kayıt kaydedilemedi.')}})}
async function deleteRecurring(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring||!confirm(`${recurring.name} planı silinsin mi? Daha önce oluşturulmuş gerçek hareketler korunur.`))return;await remove('recurringTransactions',recurringId);$('#modal').close();await load();toast('Düzenli plan silindi')}
function enhancedPostRecurring(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring||recurring.active===false)return;const account=state.accounts.find(item=>item.id===recurring.accountId);if(!account||account.archivedAt){toast('Bu plan için aktif bir hesap seçin.');return}const income=recurring.direction==='income',amount=(recurring.amountMinor/100).toFixed(2).replace('.',',');show(`<h2 class="formTitle">Düzenli ${income?'geliri':'ödemeyi'} işle</h2><p class="formHint">Bu işlem gerçek para hareketi oluşturur ve sonraki vade tarihini ilerletir.</p><label class="field">Tutar (TL)<input required name="amount" type="text" inputmode="decimal" value="${amount}" ${recurring.variableAmount?'':'readonly'}></label><label class="field">Tarih<input required name="date" type="date" value="${recurring.nextDueDate}"></label><div class="formActions"><button>${income?'Geliri kaydet':'Ödemeyi kaydet'}</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const amountMinor=FinanceCore.minor(form.get('amount')),date=FinanceCore.date(form.get('date'));if(amountMinor<=0)throw new Error('Tutar sıfırdan büyük olmalı.');const postings=FinanceCore.ledger(income?[{accountId:recurring.accountId,amountMinor},{accountId:'income',amountMinor:-amountMinor}]:[{accountId:recurring.accountId,amountMinor:-amountMinor},{accountId:'expense',amountMinor}]).map(posting=>({...posting,amount:posting.amountMinor/100}));await put('transactions',{id:id(),schemaVersion:3,date,note:recurring.name,category:recurring.category,postings,planned:false,recurringId});await put('recurringTransactions',{...recurring,nextDueDate:nextRecurringDate(recurring,date),updatedAt:new Date().toISOString()});await load();toast(income?'Düzenli gelir işlendi':'Düzenli ödeme işlendi')}catch(error){toast(error.message||'Düzenli kayıt işlenemedi.')}})}
document.addEventListener('click',event=>{const add=event.target.closest?.('#newRecurring'),edit=event.target.closest?.('[data-recurring-edit]'),post=event.target.closest?.('[data-recurring-post]'),del=event.target.closest?.('[data-recurring-delete]');if(add){event.preventDefault();event.stopImmediatePropagation();recurringEditor();return}if(edit){event.preventDefault();event.stopImmediatePropagation();recurringEditor(edit.dataset.recurringEdit);return}if(post){event.preventDefault();event.stopImmediatePropagation();enhancedPostRecurring(post.dataset.recurringPost);return}if(del){event.preventDefault();event.stopImmediatePropagation();deleteRecurring(del.dataset.recurringDelete)}},true);

/* Açıklanabilir 12 aylık nakit akışı: her ayın açılışı, girişleri, çıkışları ve kapanışı. */
function recurringCashByMonth(monthKey,cashAccounts){let income=0,expense=0;for(const recurring of state.recurring.filter(item=>item.active!==false)){let due=recurring.nextDueDate;for(let guard=0;guard<240&&due.slice(0,7)<=monthKey;guard++){if(due.slice(0,7)===monthKey&&cashAccounts.some(account=>account.id===recurring.accountId)){if(recurring.direction==='income')income+=recurring.amountMinor/100;else expense+=recurring.amountMinor/100}due=nextRecurringDate(recurring,due)}}for(const debt of [...state.debts,...state.loans].filter(item=>item.active!==false)){for(let payment=0;payment<Math.min(600,Number(item.remainingInstallments)||0);payment++){const due=FinanceCore.addMonths(item.nextDueDate,payment);if(due.slice(0,7)===monthKey){if(item.direction==='incoming')income+=item.monthlyPaymentMinor/100;else expense+=item.monthlyPaymentMinor/100}if(due.slice(0,7)>monthKey)break}}return {income,expense}}
function forecastModel(){const cashAccounts=state.accounts.filter(account=>isLiquidAccount(account)&&!account.archivedAt&&account.includeInTotals!==false),scenario=currentForecastScenario(),monthlyScenarioIncome=(scenario?.monthlyIncomeMinor||0)/100,monthlyScenarioExpense=(scenario?.monthlyExpenseMinor||0)/100;let closing=cashAccounts.reduce((total,account)=>total+accountBalance(account),0),rows=[];for(let index=0;index<12;index++){const monthStart=FinanceCore.addMonths(`${dateISO().slice(0,8)}01`,index),monthKey=monthStart.slice(0,7),opening=closing,planned={income:0,expense:0};for(const transaction of state.transactions.filter(item=>item.planned&&item.date>dateISO()&&item.date.startsWith(monthKey))){for(const posting of transaction.postings.filter(item=>cashAccounts.some(account=>account.id===item.accountId))){if(entryAmount(posting)>=0)planned.income+=entryAmount(posting);else planned.expense+=Math.abs(entryAmount(posting))}}const recurring=recurringCashByMonth(monthKey,cashAccounts),cardPayments=state.accounts.filter(account=>account.type==='card').reduce((total,account)=>{const statement=cardStatementPreview(account);return total+(statement?.dueDate?.startsWith(monthKey)?statement.outstandingMinor/100:0)},0),income=planned.income+recurring.income+monthlyScenarioIncome,expense=planned.expense+recurring.expense+cardPayments+monthlyScenarioExpense;closing=opening+income-expense;rows.push({monthStart,monthKey,opening,income,expense,cardPayments,recurringExpense:recurring.expense,plannedExpense:planned.expense,closing})}return rows}
function renderForecastDetail(rows){const analytics=$('#analytics');if(!analytics)return;let card=$('#forecastDetailCard');if(!card){card=document.createElement('article');card.id='forecastDetailCard';card.className='glass-card';card.innerHTML='<div class="eyebrow">12 AYLIK NAKİT AKIŞI</div><h2>Aylık plan ayrıntısı</h2><p id="forecastPressure" class="formHint"></p><div id="forecastDetailList" class="budget-list"></div>';const forecast=$('#forecast');if(forecast)forecast.after(card);else analytics.append(card)}const pressure=rows.filter(row=>row.closing<0),pressureText=pressure.length?`${pressure.length} ayda tahmini bakiye negatife düşüyor: ${pressure.map(row=>new Date(`${row.monthStart}T12:00`).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})).join(', ')}.`:'Mevcut planla tahmini bakiyeniz 12 ay boyunca pozitif kalıyor.';$('#forecastPressure').textContent=pressureText;$('#forecastDetailList').innerHTML=rows.map(row=>`<div class="budget-row"><b><span>${new Date(`${row.monthStart}T12:00`).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</span><span class="${row.closing<0?'expense':'income'}">${money(row.closing)}</span></b><small>Açılış: ${money(row.opening)} • Giriş: ${money(row.income)} • Çıkış: ${money(row.expense)}${row.cardPayments?` • Kart ödemesi: ${money(row.cardPayments)}`:''}</small></div>`).join('')}
function renderForecast(){const rows=forecastModel(),max=Math.max(1,...rows.map(row=>Math.abs(row.closing)));$('#forecast').innerHTML=rows.map(row=>{const [year,month]=row.monthStart.split('-');return `<div class="month"><span>${new Date(Number(year),Number(month)-1,1).toLocaleDateString('tr-TR',{month:'short',year:'2-digit'})}</span><div class="bar"><i style="width:${Math.max(3,Math.abs(row.closing)/max*100)}%"></i></div><b>${money(row.closing)}</b></div>`}).join('');renderForecastDetail(rows)}

/* Kredi, borç ve alacak planları: faiz/masraf bilgileri ile aynı uzlaştırma kuralı. */
function enhancedDebtForm(){show(`<h2 class="formTitle">Planlı borç / alacak ekle</h2><p class="formHint">Bu plan tahmine vade ekler. Gerçek para hareketini kaydetmek için vade gününde “İşle” seçeneğini kullanın.</p><label class="field">Plan türü<select name="kind"><option value="loan">Kredi / finansman</option><option value="debt">Ödenecek borç</option><option value="receivable">Tahsil edilecek alacak</option></select></label><label class="field">Kişi / kurum / ad<input required name="name" maxlength="80" placeholder="Örn. Taşıt kredisi"></label><label class="field">Başlangıç anaparası (TL)<input required name="principal" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Kalan tutar (TL)<input required name="remaining" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Aylık tahsilat / ödeme (TL)<input required name="monthlyPayment" type="text" inputmode="decimal" placeholder="0,00"></label><label class="field">Kalan vade adedi<input required name="remainingInstallments" type="number" min="1" max="600" inputmode="numeric" value="12"></label><label class="field">Yıllık faiz oranı (%)<input name="annualRate" type="text" inputmode="decimal" value="0,00"></label><label class="field">KKDF / BSMV / diğer masraflar (TL)<input name="fees" type="text" inputmode="decimal" value="0,00"></label><label class="field">İlk vade tarihi<input required name="nextDueDate" type="date" value="${dateISO()}"></label><label class="field">Not (isteğe bağlı)<input name="note" maxlength="140"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const kind=String(form.get('kind')),name=String(form.get('name')||'').trim(),principalMinor=FinanceCore.minor(form.get('principal')),remainingMinor=FinanceCore.minor(form.get('remaining')),monthlyPaymentMinor=FinanceCore.minor(form.get('monthlyPayment')),feesMinor=FinanceCore.minor(form.get('fees')||0),rateText=String(form.get('annualRate')||'0').trim().replace('.' , ',');const annualRateBps=FinanceCore.minor(rateText)/1;if(!name||principalMinor<=0||remainingMinor<=0||monthlyPaymentMinor<=0||feesMinor<0)throw new Error('Geçerli tutarlar girin.');if(!Number.isSafeInteger(annualRateBps)||annualRateBps<0||annualRateBps>1000000)throw new Error('Faiz oranı geçersiz.');const record={id:id(),schemaVersion:3,kind,name,direction:kind==='receivable'?'incoming':'outgoing',principalMinor,remainingMinor,monthlyPaymentMinor,remainingInstallments:Math.max(1,Number(form.get('remainingInstallments'))||0),annualRateBps,feesMinor,nextDueDate:FinanceCore.date(form.get('nextDueDate')),note:String(form.get('note')||'').trim(),active:true,createdAt:new Date().toISOString()};await put(kind==='loan'?'loans':'debts',record);await load();toast(kind==='receivable'?'Alacak planı eklendi':'Ödeme planı eklendi')}catch(error){toast(error.message||'Plan kaydedilemedi.')}})}
async function enhancedSettleDebtForm(debtId){const inLoans=state.loans.some(item=>item.id===debtId),debt=(inLoans?state.loans:state.debts).find(item=>item.id===debtId);if(!debt||debt.active===false)return;show(`<h2 class="formTitle">Vade / tahsilat işle</h2><p class="formHint">Önce gerçek para hareketini uygulamada kaydedin. Bu adım yalnızca planın kalan tutarını uzlaştırır.</p><p class="formHint">${esc(debt.name)} — kalan ${money(debt.remainingMinor/100)}</p><label class="field">İşlenen tutar (TL)<input required name="amount" type="text" inputmode="decimal" value="${(Math.min(debt.monthlyPaymentMinor,debt.remainingMinor)/100).toFixed(2).replace('.',',')}"></label><label class="field">Tarih<input required name="date" type="date" value="${debt.nextDueDate}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const amountMinor=FinanceCore.minor(form.get('amount')),settlementDate=FinanceCore.date(form.get('date'));if(amountMinor<=0||amountMinor>debt.remainingMinor)throw new Error('Tutar sıfırdan büyük olmalı ve kalan tutarı aşmamalı.');const remainingMinor=debt.remainingMinor-amountMinor,remainingInstallments=remainingMinor===0?0:Math.max(1,Math.ceil(remainingMinor/debt.monthlyPaymentMinor));await put(inLoans?'loans':'debts',{...debt,remainingMinor,remainingInstallments,nextDueDate:remainingMinor===0?debt.nextDueDate:FinanceCore.addMonths(settlementDate,1),active:remainingMinor>0,updatedAt:new Date().toISOString()});await put('debtSettlements',{id:id(),schemaVersion:2,debtId,amountMinor,date:settlementDate,direction:debt.direction||'outgoing',kind:debt.kind||'debt'});await load();toast(remainingMinor===0?'Plan kapatıldı':'Kalan tutar ve sonraki vade güncellendi')}catch(error){toast(error.message||'Vade işlenemedi.')}})}
debtForm=enhancedDebtForm;settleDebtForm=enhancedSettleDebtForm;

/* Gelişmiş bütçeler: genel, kategori veya alt kategori; aylık ya da özel dönem. */
function budgetPeriodRange(budget){const today=dateISO(),[year,month,day]=today.split('-').map(Number),startDay=budget.period==='custom'?Math.max(1,Math.min(31,Number(budget.periodStartDay)||1)):1;let startYear=year,startMonth=month;if(day<startDay){startMonth--;if(startMonth===0){startMonth=12;startYear--}}const start=FinanceCore.calendarDay(startYear,startMonth,startDay),end=FinanceCore.addDays(FinanceCore.addMonths(start,1),-1);return {start,end,label:budget.period==='custom'?`${fmtDate(start)} – ${fmtDate(end)}`:new Date(year,month-1,1).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}}
function budgetSpendingMinor(budget){const period=budgetPeriodRange(budget);return state.transactions.filter(transaction=>txType(transaction)==='expense'&&!transaction.planned&&transaction.date>=period.start&&transaction.date<=period.end).filter(transaction=>budget.scope==='overall'||(!budget.subcategory?transaction.category===budget.category:transaction.category===budget.category&&transaction.subcategory===budget.subcategory)).reduce((total,transaction)=>total+Math.round(entryAmount(transaction.postings.find(posting=>posting.accountId==='expense')||{})*100),0)}
function enhancedBudgetForm(){const categories=availableCategories();show(`<h2 class="formTitle">Bütçe oluştur</h2><label class="field">Bütçe türü<select name="scope"><option value="category">Kategori bütçesi</option><option value="subcategory">Alt kategori bütçesi</option><option value="overall">Toplam harcama bütçesi</option></select></label><label class="field" data-budget-category>İlgili kategori<select name="category">${categories.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}</select></label><label class="field" data-budget-subcategory>Alt kategori<select name="subcategory"><option value="">Önce kategori seçin</option></select></label><label class="field">Dönem<select name="period"><option value="monthly">Takvim ayı</option><option value="custom">Özel aylık dönem</option></select></label><label class="field" data-budget-start-day>Özel dönem başlangıç günü<input name="periodStartDay" type="number" min="1" max="31" inputmode="numeric" value="1"></label><label class="field">Limit (TL)<input required name="limit" type="text" inputmode="decimal" placeholder="0,00"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const scope=String(form.get('scope')),category=scope==='overall'?'__overall__':String(form.get('category')||''),subcategory=scope==='subcategory'?String(form.get('subcategory')||''):'';if((scope==='category'&&!category)||(scope==='subcategory'&&(!category||!subcategory)))throw new Error('Bütçe kapsamını seçin.');const limitMinor=FinanceCore.minor(form.get('limit'));if(limitMinor<=0)throw new Error('Limit sıfırdan büyük olmalı.');const period=String(form.get('period')),periodStartDay=Math.max(1,Math.min(31,Number(form.get('periodStartDay'))||1)),existing=state.budgets.find(item=>item.active!==false&&item.scope===scope&&item.category===category&&(item.subcategory||'')===subcategory&&item.period===period&&(item.periodStartDay||1)===periodStartDay);await put('budgets',{...(existing||{}),id:existing?.id||id(),schemaVersion:2,scope,category,subcategory,limitMinor,period,periodStartDay,active:true,updatedAt:new Date().toISOString()});await load();toast('Bütçe kaydedildi')}catch(error){toast(error.message||'Bütçe kaydedilemedi.')}});const scope=$('#formContent select[name="scope"]'),category=$('#formContent select[name="category"]'),subcategory=$('#formContent select[name="subcategory"]'),sync=()=>{const isSub=scope.value==='subcategory',isOverall=scope.value==='overall';document.querySelector('[data-budget-category]').style.display=isOverall?'none':'';document.querySelector('[data-budget-subcategory]').style.display=isSub?'':'none';const rows=subcategoriesFor(category.value);subcategory.innerHTML=`<option value="">Alt kategori seçin</option>${rows.map(item=>`<option value="${esc(item.name)}">${esc(item.name)}</option>`).join('')}`};scope.onchange=sync;category.onchange=sync;sync()}
function enhancedRenderBudgets(){const budgets=state.budgets.filter(budget=>budget.active!==false),details=budgets.map(budget=>({budget,spentMinor:budgetSpendingMinor(budget),period:budgetPeriodRange(budget)})),limitMinor=details.reduce((total,item)=>total+item.budget.limitMinor,0),spentMinor=details.reduce((total,item)=>total+item.spentMinor,0),percent=limitMinor?Math.round(spentMinor/limitMinor*100):0,percentElement=$('#budgetPercent'),summary=$('#budgetSummary');if(percentElement)percentElement.textContent=`${percent}%`;if(summary)summary.textContent=limitMinor?`${money(Math.max(0,(limitMinor-spentMinor)/100))} limit kaldı`:'Bütçe tanımla';$('#budgetList').innerHTML=details.length?details.map(({budget,spentMinor,period})=>{const remaining=budget.limitMinor-spentMinor,pct=Math.min(100,Math.round(spentMinor/budget.limitMinor*100)),title=budget.scope==='overall'?'Toplam harcama':budget.subcategory?`${budget.category} › ${budget.subcategory}`:budget.category;return `<div class="budget-row"><b><span>${esc(title)}</span><span>${money(spentMinor/100)} / ${money(budget.limitMinor/100)}</span></b><small>${esc(period.label)} • <span class="${remaining<0?'expense':'income'}">${remaining<0?money(Math.abs(remaining)/100)+' aşıldı':money(remaining/100)+' kaldı'}</span></small><div class="track"><i style="width:${pct}%"></i></div></div>`}).join(''):'<div class="budget-row"><b>Henüz bütçe yok</b><small>Kategori, alt kategori veya toplam harcama için limit ekleyin.</small></div>';$('#goalsList').innerHTML=state.goals.length?state.goals.map(goal=>{const pct=Math.min(100,Math.round(goal.currentMinor/goal.targetMinor*100));return `<div class="budget-row"><b><span>${esc(goal.name)}</span><span>${pct}%</span></b><small>${money(goal.currentMinor/100)} / ${money(goal.targetMinor/100)}</small><div class="track"><i style="width:${pct}%"></i></div><button type="button" class="textButton" data-goal-contribution="${goal.id}">Katkı ekle</button></div>`}).join(''):'<div class="budget-row"><b>Henüz birikim hedefi yok</b><small>Bir hedef ekleyerek ilerlemeni takip et.</small></div>'}
budgetForm=enhancedBudgetForm;renderBudgets=enhancedRenderBudgets;

/* Finans takvimi: aylık görünümün yanında haftalık ve günlük odak. */
let calendarView='month',calendarAnchorDate=dateISO();
function calendarDateRange(){if(calendarView==='day')return {start:calendarAnchorDate,end:calendarAnchorDate};if(calendarView==='week'){const date=new Date(`${calendarAnchorDate}T12:00`),offset=(date.getDay()+6)%7,dateValue=FinanceCore.addDays(calendarAnchorDate,-offset);return {start:dateValue,end:FinanceCore.addDays(dateValue,6)}}const start=`${calendarAnchorDate.slice(0,7)}-01`;return {start,end:FinanceCore.addDays(FinanceCore.addMonths(start,1),-1)}}
