/* Ana sayfa düzeni yalnızca bu cihazdaki görünüm tercihidir; finansal kayıtlara dokunmaz. */
const DASHBOARD_CARDS=[['wealth','Toplam bakiye'],['monthStats','Aylık gelir ve harcama'],['goals','Aylık hedefler'],['financial','Finansal özet'],['upcoming','Yaklaşan ödemeler']];
