document.addEventListener('click',event=>{const open=event.target.closest?.('[data-dashboard-preferences]'),toggle=event.target.closest?.('[data-dashboard-toggle]'),move=event.target.closest?.('[data-dashboard-move]');if(open){event.preventDefault();event.stopImmediatePropagation();dashboardPreferencesForm();return}if(toggle){event.preventDefault();event.stopImmediatePropagation();const prefs=dashboardPreferences(),hidden=new Set(prefs.hidden||[]),key=toggle.dataset.dashboardToggle;hidden.has(key)?hidden.delete(key):hidden.add(key);saveDashboardPreferences({...prefs,hidden:[...hidden]});applyDashboardPreferences();dashboardPreferencesForm();return}if(move){event.preventDefault();event.stopImmediatePropagation();const prefs=dashboardPreferences(),order=Array.isArray(prefs.order)?prefs.order:DASHBOARD_CARDS.map(([key])=>key),index=order.indexOf(move.dataset.dashboardKey),target=index+(move.dataset.dashboardMove==='up'?-1:1);if(target>=0&&target<order.length){[order[index],order[target]]=[order[target],order[index]];saveDashboardPreferences({...prefs,order});applyDashboardPreferences();dashboardPreferencesForm()}}},true);
