/* Kart taksit çizelgesi, satın alma kaydındaki vade bilgilerini değiştirmeden gösterir. */
function cardInstallmentTimeline(cardId){const card=state.accounts.find(item=>item.id===cardId),purchases=state.cardPurchases.filter(item=>item.cardAccountId===cardId);if(!card)return;const rows=purchases.flatMap(purchase=>(purchase.installments||[]).map((item,index)=>({purchase,date:item.dueDate,amountMinor:item.amountMinor,status:item.status,index}))).filter(item=>item.date>=dateISO()).sort((a,b)=>a.date.localeCompare(b.date));const monthly={};for(const row of rows){const key=row.date.slice(0,7);monthly[key]=(monthly[key]||0)+row.amountMinor}show(`<h2 class="formTitle">${esc(card.name)} taksit planı</h2><p class="formHint">Kart borcu alışveriş anında oluşur; bu çizelge gider tanıma ve gelecek vade görünümüdür. Banka hesabından ödeme ayrıca “Ödeme yap” ile kaydedilir.</p><h3 class="formTitle" style="font-size:16px">Aylık gelecek yük</h3>${Object.entries(monthly).map(([month,amount])=>`<div class="budget-row"><b><span>${new Date(`${month}-01T12:00`).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</span><span>${money(amount/100)}</span></b></div>`).join('')||'<p class="formHint">Gelecek taksit yok.</p>'}<h3 class="formTitle" style="font-size:16px;margin-top:16px">Vade listesi</h3>${rows.slice(0,24).map(row=>`<div class="budget-row"><b><span>${fmtDate(row.date)} • ${esc(row.purchase.note||'Taksitli alışveriş')}</span><span>${money(row.amountMinor/100)}</span></b><small>${row.status==='posted'?'İşlendi':'Planlandı'} • ${row.index+1}/${row.purchase.installments.length}. taksit</small></div>`).join('')||'<p class="formHint">Gösterilecek taksit yok.</p>'}<div class="formActions"><button type="button" onclick="document.getElementById('modal').close()">Kapat</button></div>`,async()=>{})}
function renderCardInstallmentControls(){document.querySelectorAll('.accountCard.cardType[data-account-id]').forEach(element=>{const card=state.accounts.find(item=>item.id===element.dataset.accountId);if(!card||element.querySelector('[data-card-installments]'))return;const count=state.cardPurchases.filter(item=>item.cardAccountId===card.id).flatMap(item=>item.installments||[]).filter(item=>item.dueDate>=dateISO()).length;if(!count)return;const button=document.createElement('button');button.type='button';button.className='textButton';button.dataset.cardInstallments=card.id;button.textContent=`${count} taksit`;element.append(button)})}
