function renderCashFlowReport(){const analytics=$('#analytics');if(!analytics)return;let card=$('#cashFlowReportCard');if(!card){card=document.createElement('article');card.id='cashFlowReportCard';card.className='glass-card';card.innerHTML='<div class="eyebrow">NAKİT AKIŞI</div><h2>Gerçek para hareketi</h2><div class="stat-grid" style="margin:14px 0"><article><small>NAKİT GİRİŞİ</small><b id="cashFlowIn" style="font-size:16px"></b></article><article><small>NAKİT ÇIKIŞI</small><b id="cashFlowOut" style="font-size:16px"></b></article></div><p id="cashFlowDetail" class="formHint"></p>';const period=$('#periodReportCard');if(period)period.after(card);else analytics.append(card)}const base=`${dateISO().slice(0,8)}01`,start=FinanceCore.addMonths(base,-(analyticsPeriodMonths-1)),cashIds=new Set(state.accounts.filter(account=>isLiquidAccount(account)&&!account.archivedAt).map(account=>account.id));let incoming=0,outgoing=0,internalTransfers=0;for(const transaction of state.transactions.filter(item=>!item.planned&&item.date>=start&&item.date<=dateISO())){const cashPostings=transaction.postings.filter(posting=>cashIds.has(posting.accountId));if(cashPostings.length>=2){internalTransfers++;continue}for(const posting of cashPostings){const amount=entryAmount(posting);if(amount>0)incoming+=amount;else outgoing+=Math.abs(amount)}}$('#cashFlowIn').textContent=money(incoming);$('#cashFlowOut').textContent=money(outgoing);$('#cashFlowDetail').textContent=`Net nakit akışı: ${money(incoming-outgoing)}${internalTransfers?` • ${internalTransfers} hesap içi transfer rapora dahil edilmedi.`:''} Kart ödemeleri nakit çıkışıdır; kart alışverişinin kendisi değildir.`}
