/* Şifreli yedek geri yükleme önizlemesi, mevcut veriye dokunmadan önce kapsamı gösterir. */
async function restoreWithPreview(file){try{const envelope=JSON.parse(await file.text());if(envelope.format!=='cep-finans-backup'||!Number.isInteger(envelope.version)||envelope.version>4)throw new Error('Desteklenmeyen yedek.');const pass=prompt('Yedek parolası:');if(!pass)return;const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(envelope.iv)},await derive(pass,unb64(envelope.salt)),unb64(envelope.ciphertext)),data=JSON.parse(new TextDecoder().decode(plain));if(!Array.isArray(data.accounts)||!Array.isArray(data.transactions))throw new Error('Yedek içeriği geçersiz.');for(const storeName of BACKUP_STORES)if(!Array.isArray(data[storeName]))data[storeName]=[];for(const item of data.attachments)if(item.blob?.base64)item.blob=new Blob([largeUnb64(item.blob.base64)],{type:item.blob.type||item.type||'application/octet-stream'});const counts=BACKUP_STORES.filter(storeName=>data[storeName].length).map(storeName=>`${storeName}: ${data[storeName].length}`).join(' • ')||'Kayıt yok',created=data.createdAt?new Date(data.createdAt).toLocaleString('tr-TR'):'Tarih bilgisi yok';show(`<h2 class="formTitle">Yedek geri yükleme</h2><p class="formHint">Yedek tarihi: ${esc(created)}</p><p class="formHint">${esc(counts)}</p><p class="formHint">Onaydan sonra bu cihazdaki mevcut finansal kayıtların tamamı atomik olarak yedektekilerle değişir. İşlem başarısız olursa mevcut veri korunur.</p><div class="formActions"><button>Geri yüklemeyi onayla</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async()=>{await replaceCoreData(data);await load();toast('Yedek güvenle geri yüklendi')})}catch(error){toast('Yedek açılamadı: parola veya dosya hatalı.')}$('restoreFile').value=''}
