function validateBackupEnvelope(envelope){if(!envelope||envelope.format!=='cep-finans-backup'||!Number.isInteger(envelope.version)||envelope.version<3||envelope.version>4)throw new Error('Desteklenmeyen yedek sürümü.');if(envelope.kdf!=='PBKDF2-SHA-256'||envelope.iterations!==250000)throw new Error('Yedek anahtar türetme bilgisi geçersiz.');const decode=(value,label)=>{if(typeof value!=='string'||!value.length||!/^[A-Za-z0-9+/]+={0,2}$/.test(value))throw new Error(`${label} geçersiz.`);try{return unb64(value)}catch(error){throw new Error(`${label} geçersiz.`)}};const salt=decode(envelope.salt,'Yedek tuzu'),iv=decode(envelope.iv,'Yedek başlatma verisi'),ciphertext=decode(envelope.ciphertext,'Şifreli veri');if(salt.length!==16||iv.length!==12||ciphertext.length<=16)throw new Error('Yedek şifreleme parametreleri geçersiz.');return {salt,iv,ciphertext}}
