/* Hatırlatma ertelemesi sadece bu cihazdaki bildirim görünümünü değiştirir; vade kaydını değiştirmez. */
function reminderEventKey(event){return `${event.date}|${event.title}|${event.amountMinor||0}`}
function reminderSnoozes(){try{return JSON.parse(localStorage.getItem('cepFinansReminderSnoozes')||'{}')}catch(error){return {}}}
