function renderReminderControlV2(){const more=$('#more');if(!more||$('#reminderCard'))return;const enabled=localStorage.getItem('cepFinansNotifications')==='enabled',permission='Notification'in window?Notification.permission:'unsupported',card=document.createElement('article');card.id='reminderCard';card.className='settings-card';card.innerHTML=`<i>◷</i><div><h2>Ödeme hatırlatmaları</h2><p>${enabled&&permission==='granted'?'Bildirimler etkin.':'Uygulama açıldığında yaklaşan ödemeler gösterilir.'}</p></div><button type="button" class="textButton" data-reminder-list>İncele</button><button type="button" class="textButton" data-reminder-enable>${enabled&&permission==='granted'?'Etkin':'Etkinleştir'}</button>`;const privacy=more.querySelector('.privacy');if(privacy)more.insertBefore(card,privacy);else more.append(card)}
