document.addEventListener('click',event=>{const list=event.target.closest?.('[data-reminder-list]'),snooze=event.target.closest?.('[data-reminder-snooze]');if(list){event.preventDefault();event.stopImmediatePropagation();reminderListForm();return}if(snooze){event.preventDefault();event.stopImmediatePropagation();const snoozes=reminderSnoozes();snoozes[snooze.dataset.reminderSnooze]=Date.now()+24*60*60*1000;saveReminderSnoozes(snoozes);reminderListForm()}},true);

