categoryManager=categoryManagerV3;document.addEventListener('click',event=>{const merge=event.target.closest?.('[data-subcategory-merge]');if(!merge)return;event.preventDefault();event.stopImmediatePropagation();mergeSubcategoryForm(merge.dataset.subcategoryMerge)},true);

/* Ekstrede görünen faiz ve masraf, kart borcu ve gider kaydını aynı anda, dengeli oluşturur. */
function cardStatementFormV2(accountId){const account=state.accounts.find(item=>item.id===accountId),preview=account?cardStatementPreview(account):null;if(!account||account.type!=='card'){toast('Kredi kartı bulunamadı.');return}if(!preview){toast('Ekstre doğrulamak için kartın kesim günü ve en az bir kart harcaması gerekli.');return}const existing=savedStatement(account.id,preview.closingDate),amount=((existing?.statementMinor??preview.purchaseMinor)/100).toFixed(2).replace('.',','),chargesRecorded=Boolean(existing?.chargeTransactionIds?.length);show(`<h2 class="formTitle">Ekstreyi doğrula</h2><p class="formHint">${esc(account.name)} • Kesim: ${fmtDate(preview.closingDate)} • Son ödeme: ${fmtDate(preview.dueDate)}</p><p class="formHint">Uygulamanın hesapladığı dönem harcaması: <b>${money(preview.purchaseMinor/100)}</b>. Faiz ve masrafları eklerseniz kart borcu ile gider kaydı birlikte oluşur.</p><label class="field">Ekstredeki dönem borcu (TL)<input required name="statement" type="text" inputmode="decimal" value="${amount}"></label><label class="field">Ekstre faizi (TL)<input name="interest" type="text" inputmode="decimal" value="0,00" ${chargesRecorded?'disabled':''}></label><label class="field">Diğer banka masrafları (TL)<input name="fees" type="text" inputmode="decimal" value="0,00" ${chargesRecorded?'disabled':''}></label>${chargesRecorded?'<p class="formHint">Bu ekstre için faiz/masraf gideri daha önce kaydedildi; çift kayıt önlendi.</p>':''}<label class="field">Not (isteğe bağlı)<input name="note" maxlength="140" value="${esc(existing?.note||'')}" placeholder="Örn. banka ekstresi kontrolü"></label><div class="formActions"><button>Doğrulamayı kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const statementMinor=FinanceCore.minor(form.get('statement')),interestMinor=chargesRecorded?0:FinanceCore.minor(form.get('interest')||0),feesMinor=chargesRecorded?0:FinanceCore.minor(form.get('fees')||0);if(statementMinor<0||interestMinor<0||feesMinor<0)throw new Error('Tutar negatif olamaz.');const chargeMinor=interestMinor+feesMinor,chargeTransactionIds=[...(existing?.chargeTransactionIds||[])];if(chargeMinor){const postings=FinanceCore.ledger([{accountId:account.id,amountMinor:-chargeMinor},{accountId:'expense',amountMinor:chargeMinor}]).map(posting=>({...posting,amount:posting.amountMinor/100})),charge={id:id(),schemaVersion:3,date:preview.closingDate,note:`${account.name} ekstre ${interestMinor&&feesMinor?'faizi ve masrafı':interestMinor?'faizi':'masrafı'}`,category:'Finansman',tags:['ekstre','faiz-masraf'],postings,planned:false,cardStatementCharge:true,cardStatementClosingDate:preview.closingDate,createdAt:new Date().toISOString()};await put('transactions',charge);chargeTransactionIds.push(charge.id)}const differenceMinor=statementMinor-preview.purchaseMinor-chargeMinor;await put('cardStatements',{id:existing?.id||id(),schemaVersion:2,cardAccountId:account.id,closingDate:preview.closingDate,dueDate:preview.dueDate,calculatedMinor:preview.purchaseMinor,statementMinor,differenceMinor,chargeTransactionIds,note:String(form.get('note')||'').trim(),verifiedAt:new Date().toISOString()});await load();toast(chargeMinor?'Ekstre doğrulandı; faiz/masraf gideri kaydedildi.':differenceMinor?`Ekstre farkı kaydedildi: ${money(Math.abs(differenceMinor)/100)}`:'Ekstre uygulama kaydıyla uyuşuyor.')}catch(error){toast(error.message||'Ekstre doğrulanamadı.')}})}
