/* Kredi faiz değişiklikleri doğru kredi/borç deposunda saklanır; ara ödeme de açıkça işaretlenir. */
function amortizationFormV2(debtId){const inLoans=state.loans.some(item=>item.id===debtId),debt=(inLoans?state.loans:state.debts).find(item=>item.id===debtId);if(!debt||debt.direction==='incoming')return;const rate=((debt.annualRateBps||0)/100).toFixed(2).replace('.',','),changes=debt.rateChanges||[];show(`<h2 class="formTitle">Faiz / amortisman</h2><p class="formHint">Faiz değişikliğini kaydetmek geçmiş vade kayıtlarını değiştirmez; sonraki amortisman görünümü güncel oranla hesaplanır.</p><label class="field">Yıllık faiz oranı (%)<input required name="rate" type="text" inputmode="decimal" value="${rate}"></label><label class="field">Oranın geçerli olduğu tarih<input required name="effectiveDate" type="date" value="${dateISO()}"></label>${changes.length?`<p class="formHint">Önceki değişiklikler: ${changes.slice(-3).map(item=>`${fmtDate(item.effectiveDate)} %${(item.annualRateBps/100).toLocaleString('tr-TR',{minimumFractionDigits:2})}`).join(' • ')}</p>`:''}<div class="formActions"><button>Kaydet ve tabloyu göster</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const annualRateBps=FinanceCore.minor(form.get('rate')),effectiveDate=FinanceCore.date(form.get('effectiveDate'));if(annualRateBps<0||annualRateBps>1000000)throw new Error('Faiz oranı geçersiz.');const rateChanges=annualRateBps===debt.annualRateBps?[...changes]:[...changes,{effectiveDate,annualRateBps,recordedAt:new Date().toISOString()}].slice(-60);await put(inLoans?'loans':'debts',{...debt,annualRateBps,rateChanges,updatedAt:new Date().toISOString()});await load();setTimeout(()=>showAmortization(debtId),0)}catch(error){toast(error.message||'Faiz oranı kaydedilemedi.')}})}
async function enhancedSettleDebtFormV2(debtId){const inLoans=state.loans.some(item=>item.id===debtId),debt=(inLoans?state.loans:state.debts).find(item=>item.id===debtId);if(!debt||debt.active===false)return;const standard=Math.min(debt.monthlyPaymentMinor,debt.remainingMinor);show(`<h2 class="formTitle">Vade / ara ödeme işle</h2><p class="formHint">Standart vade: ${money(standard/100)}. Daha yüksek tutar girerseniz ara ödeme / erken kapama olarak kaydedilir. Önce gerçek para hareketini uygulamada kaydedin.</p><p class="formHint">${esc(debt.name)} — kalan ${money(debt.remainingMinor/100)}</p><label class="field">İşlenen tutar (TL)<input required name="amount" type="text" inputmode="decimal" value="${(standard/100).toFixed(2).replace('.',',')}"></label><label class="field">Tarih<input required name="date" type="date" value="${debt.nextDueDate}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const amountMinor=FinanceCore.minor(form.get('amount')),settlementDate=FinanceCore.date(form.get('date'));if(amountMinor<=0||amountMinor>debt.remainingMinor)throw new Error('Tutar sıfırdan büyük olmalı ve kalan tutarı aşmamalı.');const remainingMinor=debt.remainingMinor-amountMinor,remainingInstallments=remainingMinor===0?0:Math.max(1,Math.ceil(remainingMinor/debt.monthlyPaymentMinor)),earlyPayment=amountMinor>standard;await put(inLoans?'loans':'debts',{...debt,remainingMinor,remainingInstallments,nextDueDate:remainingMinor===0?debt.nextDueDate:FinanceCore.addMonths(settlementDate,1),active:remainingMinor>0,updatedAt:dateISO()});await put('debtSettlements',{id:id(),schemaVersion:3,debtId,amountMinor,date:settlementDate,direction:debt.direction||'outgoing',kind:debt.kind||'debt',earlyPayment});await load();toast(remainingMinor===0?'Plan erken kapatıldı':earlyPayment?'Ara ödeme kaydedildi; kalan tutar güncellendi':'Kalan tutar ve sonraki vade güncellendi')}catch(error){toast(error.message||'Ödeme işlenemedi.')}})}
amortizationForm=amortizationFormV2;settleDebtForm=enhancedSettleDebtFormV2;

/* Tahmin, nakit hareketi ile hedef için ayrılması önerilen tutarı birbirine karıştırmaz. */
function suggestedGoalSavingsMinor(monthKey){let total=0;for(const goal of state.goals.filter(item=>item.status!=='paused'&&item.status!=='completed'&&item.targetDate)){if(monthKey>goal.targetDate.slice(0,7))continue;const remaining=Math.max(0,(goal.targetMinor||0)-(goal.currentMinor||0)),start=`${dateISO().slice(0,7)}-01`,end=`${goal.targetDate.slice(0,7)}-01`,months=Math.max(1,Math.round((new Date(`${end}T12:00`)-new Date(`${start}T12:00`))/(30.4375*86400000))+1);total+=Math.ceil(remaining/months)}return total}
function forecastModelV2(){const cashAccounts=state.accounts.filter(account=>isLiquidAccount(account)&&!account.archivedAt&&account.includeInTotals!==false),scenario=currentForecastScenario(),monthlyScenarioIncome=(scenario?.monthlyIncomeMinor||0)/100,monthlyScenarioExpense=(scenario?.monthlyExpenseMinor||0)/100,monthlyScenarioSavings=(scenario?.monthlySavingsMinor||0)/100,oneTimeExpense=(scenario?.oneTimeExpenseMinor||0)/100;let closing=cashAccounts.reduce((total,account)=>total+accountBalance(account),0),rows=[];for(let index=0;index<12;index++){const monthStart=FinanceCore.addMonths(`${dateISO().slice(0,8)}01`,index),monthKey=monthStart.slice(0,7),opening=closing,planned={income:0,expense:0};for(const transaction of state.transactions.filter(item=>item.planned&&item.date>dateISO()&&item.date.startsWith(monthKey))){for(const posting of transaction.postings.filter(item=>cashAccounts.some(account=>account.id===item.accountId))){if(entryAmount(posting)>=0)planned.income+=entryAmount(posting);else planned.expense+=Math.abs(entryAmount(posting))}}const recurring=recurringCashByMonth(monthKey,cashAccounts),cardPayments=state.accounts.filter(account=>account.type==='card').reduce((total,account)=>{const statement=cardStatementPreview(account);return total+(statement?.dueDate?.startsWith(monthKey)?statement.outstandingMinor/100:0)},0),income=planned.income+recurring.income+monthlyScenarioIncome,expense=planned.expense+recurring.expense+cardPayments+monthlyScenarioExpense+(index===0?oneTimeExpense:0),goalSavings=suggestedGoalSavingsMinor(monthKey)/100+monthlyScenarioSavings;closing=opening+income-expense;rows.push({monthStart,monthKey,opening,income,expense,cardPayments,recurringExpense:recurring.expense,plannedExpense:planned.expense,goalSavings,availableDiscretionary:closing-goalSavings,closing})}return rows}
function renderForecastDetailV2(rows){const analytics=$('#analytics');if(!analytics)return;let card=$('#forecastDetailCard');if(!card){card=document.createElement('article');card.id='forecastDetailCard';card.className='glass-card';card.innerHTML='<div class="eyebrow">12 AYLIK NAKİT AKIŞI</div><h2>Aylık plan ayrıntısı</h2><p id="forecastPressure" class="formHint"></p><div id="forecastDetailList" class="budget-list"></div>';const forecast=$('#forecast');if(forecast)forecast.after(card);else analytics.append(card)}const pressure=rows.filter(row=>row.closing<0),pressureText=pressure.length?`${pressure.length} ayda tahmini bakiye negatife düşüyor: ${pressure.map(row=>new Date(`${row.monthStart}T12:00`).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})).join(', ')}.`:'Mevcut planla tahmini bakiyeniz 12 ay boyunca pozitif kalıyor.';$('#forecastPressure').textContent=pressureText;$('#forecastDetailList').innerHTML=rows.map(row=>`<div class="budget-row"><b><span>${new Date(`${row.monthStart}T12:00`).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</span><span class="${row.closing<0?'expense':'income'}">${money(row.closing)}</span></b><small>Açılış: ${money(row.opening)} • Giriş: ${money(row.income)} • Çıkış: ${money(row.expense)}${row.cardPayments?` • Kart ödemesi: ${money(row.cardPayments)}`:''}${row.goalSavings?` • Hedef için ayrılacak: ${money(row.goalSavings)} • Serbest nakit: ${money(row.availableDiscretionary)}`:''}</small></div>`).join('')}
function renderForecastV2(){const rows=forecastModelV2(),max=Math.max(1,...rows.map(row=>Math.abs(row.closing)));$('#forecast').innerHTML=rows.map(row=>{const [year,month]=row.monthStart.split('-');return `<div class="month"><span>${new Date(Number(year),Number(month)-1,1).toLocaleDateString('tr-TR',{month:'short',year:'2-digit'})}</span><div class="bar"><i style="width:${Math.max(3,Math.abs(row.closing)/max*100)}%"></i></div><b>${money(row.closing)}</b></div>`}).join('');renderForecastDetailV2(rows)}
function scenarioFormV2(scenarioId){const existing=scenarioId?state.forecastScenarios.find(item=>item.id===scenarioId):null,amount=name=>((existing?.[name]||0)/100).toFixed(2).replace('.',',');show(`<h2 class="formTitle">${existing?'Senaryoyu düzenle':'Tahmin senaryosu'}</h2><p class="formHint">Senaryo mevcut kayıtları değiştirmez; yalnızca 12 aylık plan görünümünü etkiler. Hedefe ayrılan tutar, fiziksel para hareketi olmadığı için nakit bakiyesini azaltmaz.</p><label class="field">Senaryo adı<input required name="name" maxlength="60" value="${esc(existing?.name||'')}" placeholder="Örn. İyimser"></label><label class="field">Aylık ek gelir (TL)<input required name="income" type="text" inputmode="decimal" value="${amount('monthlyIncomeMinor')}"></label><label class="field">Aylık ek gider (TL)<input required name="expense" type="text" inputmode="decimal" value="${amount('monthlyExpenseMinor')}"></label><label class="field">Aylık ek hedef ayırma (TL)<input required name="savings" type="text" inputmode="decimal" value="${amount('monthlySavingsMinor')}"></label><label class="field">İlk aya tek seferlik beklenmedik gider (TL)<input required name="oneTimeExpense" type="text" inputmode="decimal" value="${amount('oneTimeExpenseMinor')}"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const name=String(form.get('name')||'').trim(),monthlyIncomeMinor=FinanceCore.minor(form.get('income')),monthlyExpenseMinor=FinanceCore.minor(form.get('expense')),monthlySavingsMinor=FinanceCore.minor(form.get('savings')),oneTimeExpenseMinor=FinanceCore.minor(form.get('oneTimeExpense'));if(!name||[monthlyIncomeMinor,monthlyExpenseMinor,monthlySavingsMinor,oneTimeExpenseMinor].some(value=>value<0))throw new Error('Geçerli senaryo bilgileri girin.');await put('forecastScenarios',{...(existing||{}),id:existing?.id||id(),schemaVersion:2,name,monthlyIncomeMinor,monthlyExpenseMinor,monthlySavingsMinor,oneTimeExpenseMinor,updatedAt:new Date().toISOString()});await load();toast('Tahmin senaryosu kaydedildi')}catch(error){toast(error.message||'Senaryo kaydedilemedi.')}})}
forecastModel=forecastModelV2;renderForecast=renderForecastV2;scenarioForm=scenarioFormV2;

/* Tek vade değişikliği, sonraki tekrarların tarihini veya varsayılan tutarını değiştirmez. */
function recurringOccurrence(recurring){const change=recurring.nextOccurrenceOverride;if(change&&change.originalDueDate===recurring.nextDueDate)return {originalDueDate:recurring.nextDueDate,dueDate:change.dueDate,amountMinor:change.amountMinor};return {originalDueDate:recurring.nextDueDate,dueDate:recurring.nextDueDate,amountMinor:recurring.amountMinor}}
function editNextRecurringOccurrence(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring||recurring.active===false)return;const occurrence=recurringOccurrence(recurring);show(`<h2 class="formTitle">Bu vadeyi değiştir</h2><p class="formHint">Yalnızca ${fmtDate(occurrence.originalDueDate)} vadisi değişir. Sonraki vadeler ve varsayılan tutar korunur.</p><label class="field">Bu vadinin tarihi<input required name="date" type="date" min="${occurrence.originalDueDate}" max="${nextRecurringDate(recurring,occurrence.originalDueDate)}" value="${occurrence.dueDate}"></label><label class="field">Bu vadinin tutarı (TL)<input required name="amount" type="text" inputmode="decimal" value="${(occurrence.amountMinor/100).toFixed(2).replace('.',',')}"></label><div class="formActions"><button>Bu vadeyi kaydet</button><button type="button" data-recurring-once-reset="${recurring.id}">Varsayılanına döndür</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const dueDate=FinanceCore.date(form.get('date')),amountMinor=FinanceCore.minor(form.get('amount')),next=nextRecurringDate(recurring,recurring.nextDueDate);if(dueDate<recurring.nextDueDate||dueDate>next)throw new Error('Tarih bu vade ile sonraki vade arasında olmalı.');if(amountMinor<=0)throw new Error('Tutar sıfırdan büyük olmalı.');await put('recurringTransactions',{...recurring,nextOccurrenceOverride:{originalDueDate:recurring.nextDueDate,dueDate,amountMinor},updatedAt:new Date().toISOString()});await load();toast('Yalnızca bu vade değiştirildi')}catch(error){toast(error.message||'Vade değiştirilemedi.')}})}
async function resetNextRecurringOccurrence(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring)return;const {nextOccurrenceOverride,...record}=recurring;await put('recurringTransactions',{...record,updatedAt:new Date().toISOString()});await load();toast('Bu vade varsayılan planına döndürüldü')}
function enhancedPostRecurringV2(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring||recurring.active===false)return;const account=state.accounts.find(item=>item.id===recurring.accountId);if(!account||account.archivedAt){toast('Bu plan için aktif bir hesap seçin.');return}const occurrence=recurringOccurrence(recurring),income=recurring.direction==='income',amount=(occurrence.amountMinor/100).toFixed(2).replace('.',',');show(`<h2 class="formTitle">Düzenli ${income?'geliri':'ödemeyi'} işle</h2><p class="formHint">Bu işlem gerçek para hareketi oluşturur. Sonraki düzenli vade, özgün takvim kuralına göre ilerletilir.</p><label class="field">Tutar (TL)<input required name="amount" type="text" inputmode="decimal" value="${amount}" ${(recurring.variableAmount||occurrence.amountMinor!==recurring.amountMinor)?'':'readonly'}></label><label class="field">Tarih<input required name="date" type="date" value="${occurrence.dueDate}"></label><div class="formActions"><button>${income?'Geliri kaydet':'Ödemeyi kaydet'}</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const amountMinor=FinanceCore.minor(form.get('amount')),date=FinanceCore.date(form.get('date'));if(amountMinor<=0)throw new Error('Tutar sıfırdan büyük olmalı.');const postings=FinanceCore.ledger(income?[{accountId:recurring.accountId,amountMinor},{accountId:'income',amountMinor:-amountMinor}]:[{accountId:recurring.accountId,amountMinor:-amountMinor},{accountId:'expense',amountMinor}]).map(posting=>({...posting,amount:posting.amountMinor/100}));const {nextOccurrenceOverride,...withoutOverride}=recurring;await put('transactions',{id:id(),schemaVersion:3,date,note:recurring.name,category:recurring.category,postings,planned:false,recurringId,recurringOriginalDueDate:occurrence.originalDueDate});await put('recurringTransactions',{...withoutOverride,nextDueDate:nextRecurringDate(recurring,occurrence.originalDueDate),updatedAt:dateISO()});await load();toast(income?'Düzenli gelir işlendi':'Düzenli ödeme işlendi')}catch(error){toast(error.message||'Düzenli kayıt işlenemedi.')}})}
async function skipRecurringV3(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring||recurring.active===false)return;const occurrence=recurringOccurrence(recurring);if(!confirm(`${recurring.name} için ${fmtDate(occurrence.dueDate)} vadesi atlanacak. Devam edilsin mi?`))return;const {nextOccurrenceOverride,...withoutOverride}=recurring;await put('recurringTransactions',{...withoutOverride,nextDueDate:nextRecurringDate(recurring,occurrence.originalDueDate),lastSkippedDate:occurrence.originalDueDate,updatedAt:dateISO()});await load();toast('Vade atlandı; sonraki tarih ilerletildi')}
function recurringCashByMonthV2(monthKey,cashAccounts){let income=0,expense=0;for(const recurring of state.recurring.filter(item=>item.active!==false)){let originalDue=item.nextDueDate;for(let guard=0;guard<800&&originalDue.slice(0,7)<=monthKey;guard++){const occurrence=originalDue===item.nextDueDate?recurringOccurrence(item):{dueDate:originalDue,amountMinor:item.amountMinor};if(occurrence.dueDate.slice(0,7)===monthKey&&cashAccounts.some(account=>account.id===item.accountId)){if(item.direction==='income')income+=occurrence.amountMinor/100;else expense+=occurrence.amountMinor/100}originalDue=nextRecurringDate(item,originalDue)}}for(const debt of [...state.debts,...state.loans].filter(item=>item.active!==false)){for(let payment=0;payment<Math.min(600,Number(item.remainingInstallments)||0);payment++){const due=FinanceCore.addMonths(item.nextDueDate,payment);if(due.slice(0,7)===monthKey){if(item.direction==='incoming')income+=item.monthlyPaymentMinor/100;else expense+=item.monthlyPaymentMinor/100}if(due.slice(0,7)>monthKey)break}}return {income,expense}}
const cepFinansRenderRecurringV3=renderRecurring;renderRecurring=function(){cepFinansRenderRecurringV3();for(const recurring of state.recurring.filter(item=>item.active!==false)){const row=document.querySelector(`[data-recurring-post="${recurring.id}"]`);if(!row)continue;const occurrence=recurringOccurrence(recurring);if(occurrence.dueDate!==occurrence.originalDueDate){const detail=row.querySelector('small');if(detail)detail.textContent=`Tek vade: ${fmtDate(occurrence.dueDate)} • ${money(occurrence.amountMinor/100)} • İşlemek için dokunun`}if(!row.querySelector('[data-recurring-once-edit]')){const button=document.createElement('button');button.type='button';button.className='textButton';button.dataset.recurringOnceEdit=recurring.id;button.textContent='Bu vadeyi değiştir';row.append(button)}}}
enhancedPostRecurring=enhancedPostRecurringV2;skipRecurring=skipRecurringV3;recurringCashByMonth=recurringCashByMonthV2;document.addEventListener('click',event=>{const edit=event.target.closest?.('[data-recurring-once-edit]'),reset=event.target.closest?.('[data-recurring-once-reset]');if(edit){event.preventDefault();event.stopImmediatePropagation();editNextRecurringOccurrence(edit.dataset.recurringOnceEdit)}if(reset){event.preventDefault();event.stopImmediatePropagation();resetNextRecurringOccurrence(reset.dataset.recurringOnceReset)}},true);

const cepFinansCalendarWithOccurrence=calendarEvents;calendarEvents=function(month){let events=cepFinansCalendarWithOccurrence(month);for(const recurring of state.recurring.filter(item=>item.active!==false&&item.nextOccurrenceOverride?.originalDueDate===item.nextDueDate)){const occurrence=recurringOccurrence(recurring);if(occurrence.dueDate===occurrence.originalDueDate)continue;events=events.filter(event=>!(event.action==='recurring'&&event.key===recurring.id&&event.date===occurrence.originalDueDate));if(occurrence.dueDate.startsWith(month))events.push({date:occurrence.dueDate,title:recurring.name,detail:`Düzenli ${recurring.direction==='income'?'gelir':'ödeme'} • ${money(occurrence.amountMinor/100)} • Tek vade`,status:'Bekliyor',action:'recurring',key:recurring.id})}return events.sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title,'tr'))};
const cepFinansUpcomingWithOccurrence=upcomingReminderEvents;upcomingReminderEvents=function(){let events=cepFinansUpcomingWithOccurrence();for(const recurring of state.recurring.filter(item=>item.active!==false&&item.nextOccurrenceOverride?.originalDueDate===item.nextDueDate)){const occurrence=recurringOccurrence(recurring);if(occurrence.dueDate===occurrence.originalDueDate)continue;events=events.filter(event=>!(event.title===recurring.name&&event.date===occurrence.originalDueDate));const days=(new Date(`${occurrence.dueDate}T12:00`)-new Date(`${dateISO()}T12:00`))/86400000;if(days>=0&&days<=7)events.push({date:occurrence.dueDate,title:recurring.name,amountMinor:occurrence.amountMinor})}return events.sort((a,b)=>a.date.localeCompare(b.date))};

/* Yatırım hareketiyle seçilen nakit/kart hesabını tek atomik işlemde bağlamak, tüketim giderini iki kez yazmaz. */
function saveInvestmentTradeAtomically(tradeRecord,assetRecord,cashTransaction){return new Promise((resolve,reject)=>{const stores=cashTransaction?['investmentTransactions','investmentAssets','transactions','auditRecords']:['investmentTransactions','investmentAssets','auditRecords'];let tx;try{tx=db.transaction(stores,'readwrite');tx.objectStore('investmentTransactions').put(tradeRecord);tx.objectStore('investmentAssets').put(assetRecord);if(cashTransaction)tx.objectStore('transactions').put(cashTransaction);if(db.objectStoreNames.contains('auditRecords')){const audit=tx.objectStore('auditRecords'),at=new Date().toISOString();audit.put({id:id(),schemaVersion:1,store:'investmentTransactions',recordId:tradeRecord.id,action:'upsert',at});audit.put({id:id(),schemaVersion:1,store:'investmentAssets',recordId:assetRecord.id,action:'upsert',at});if(cashTransaction)audit.put({id:id(),schemaVersion:1,store:'transactions',recordId:cashTransaction.id,action:'upsert',at})}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('Yatırım hareketi kaydedilemedi.'));tx.onabort=()=>reject(tx.error||new Error('Yatırım hareketi kaydedilemedi.'))}catch(error){reject(error)}})}
function investmentTradeFormV2(assetId,kind){const asset=state.investments.find(item=>item.id===assetId);if(!asset)return;const isSale=kind==='sale',available=(asset.quantityMicros/1000000).toLocaleString('tr-TR',{maximumFractionDigits:6,useGrouping:false}),lastPrice=Number.isSafeInteger(asset.currentPriceMinor)?(asset.currentPriceMinor/100).toFixed(2).replace('.',','):'',accounts=state.accounts.filter(item=>!item.archivedAt&&['bank','cash','savings','wallet','prepaid','card'].includes(item.type));show(`<h2 class="formTitle">${isSale?'Yatırım satışı':'Yatırım alımı'}</h2><p class="formHint">${esc(asset.name)} • Eldeki miktar: ${available}</p><p class="formHint">Bir hesap seçerseniz para hareketi aynı anda kaydedilir: yatırımın ana tutarı tüketim gideri değildir; yalnızca komisyon gider olarak tanınır.</p><label class="field">Tarih<input required name="date" type="date" value="${dateISO()}"></label><label class="field">Miktar<input required name="quantity" type="text" inputmode="decimal" placeholder="Örn. 0,25"></label><label class="field">Birim ${isSale?'satış':'alış'} fiyatı (TL)<input required name="unitPrice" type="text" inputmode="decimal" value="${lastPrice}" placeholder="0,00"></label><label class="field">Komisyon / masraf (TL)<input name="fee" type="text" inputmode="decimal" value="0,00"></label><label class="field">Nakit / kart hesabı (isteğe bağlı)<select name="accountId"><option value="">Ayrı para hareketi kaydetmeyeceğim</option>${accounts.map(account=>`<option value="${account.id}">${esc(account.name)}</option>`).join('')}</select></label><label class="field">Not (isteğe bağlı)<input name="note" maxlength="140" placeholder="Örn. Aracı kurum emri"></label><div class="formActions"><button>${isSale?'Satışı kaydet':'Alımı kaydet'}</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const quantityMicrosValue=quantityMicros(form.get('quantity')),unitPriceMinor=FinanceCore.minor(form.get('unitPrice')),feeMinor=FinanceCore.minor(form.get('fee')||0),date=FinanceCore.date(form.get('date')),note=String(form.get('note')||'').trim(),accountId=String(form.get('accountId')||'');if(unitPriceMinor<=0||feeMinor<0)throw new Error('Fiyat sıfırdan büyük, komisyon sıfır veya pozitif olmalı.');const trade=FinanceCore.investmentTrade(asset.quantityMicros,asset.costPriceMinor,isSale?'sale':'buy',quantityMicrosValue,unitPriceMinor,feeMinor);if(isSale&&trade.grossMinor<feeMinor)throw new Error('Satış komisyonu satış tutarından büyük olamaz.');const tradeRecord={id:id(),schemaVersion:2,assetId:asset.id,type:isSale?'sale':'buy',date,quantityMicros:quantityMicrosValue,unitPriceMinor,feeMinor,grossMinor:trade.grossMinor,costBasisMinor:trade.costBasisMinor,realizedProfitMinor:trade.realizedProfitMinor,note,createdAt:new Date().toISOString()},assetRecord={...asset,quantityMicros:trade.nextQuantityMicros,costPriceMinor:trade.nextCostPriceMinor,updatedAt:dateISO()};let cashTransaction=null;if(accountId){const account=state.accounts.find(item=>item.id===accountId);if(!account)throw new Error('Seçilen hesap bulunamadı.');const assetAccountId=`investment:${asset.id}`;let entries;if(!isSale)entries=[{accountId,amountMinor:-(trade.grossMinor+feeMinor)},{accountId:assetAccountId,amountMinor:trade.grossMinor},...(feeMinor?[{accountId:'expense',amountMinor:feeMinor}]:[])];else{const payout=trade.grossMinor-feeMinor,profit=trade.realizedProfitMinor||0;entries=[{accountId,amountMinor:payout},{accountId:assetAccountId,amountMinor:-(trade.costBasisMinor||0)},...(profit>=0?[...(profit?[{accountId:'income',amountMinor:-profit}]:[])]:[{accountId:'expense',amountMinor:-profit}])];if(feeMinor&&profit>=0&&entries.every(entry=>entry.accountId!=='expense')){/* masraf gerçekleşen kâr hesabında zaten düşülüdür */}}const postings=FinanceCore.ledger(entries).map(posting=>({...posting,amount:posting.amountMinor/100}));cashTransaction={id:id(),schemaVersion:3,date,note:note||`${asset.name} ${isSale?'satışı':'alımı'}`,payee:'',tags:['yatırım'],category:'Yatırım',postings,planned:false,investmentTransactionId:tradeRecord.id,createdAt:new Date().toISOString()};tradeRecord.cashTransactionId=cashTransaction.id}await saveInvestmentTradeAtomically(tradeRecord,assetRecord,cashTransaction);await load();toast(isSale?`Satış kaydedildi • gerçekleşen ${trade.realizedProfitMinor>=0?'kâr':'zarar'}: ${money(Math.abs(trade.realizedProfitMinor)/100)}`:'Yatırım alımı kaydedildi')}catch(error){toast(error.message||'Yatırım hareketi kaydedilemedi.')}})}
investmentTradeForm=investmentTradeFormV2;deleteInvestment=async function(assetId){const asset=state.investments.find(item=>item.id===assetId);if(!asset)return;const history=state.investmentTransactions.filter(item=>item.assetId===assetId);if(history.some(item=>item.cashTransactionId)){toast('Bu yatırımın bağlı banka/kart hareketi var. Finansal geçmişin tutarlı kalması için silinemez; isterseniz satış veya ters kayıt ekleyin.');return}if(!confirm(`${asset.name} yatırımı${history.length?` ve ${history.length} alım-satım kaydı`:''} silinsin mi? Bu işlem geri alınamaz.`))return;for(const valuation of await all('assetValuations'))if(valuation.assetId===assetId)await remove('assetValuations',valuation.id);for(const row of history)await remove('investmentTransactions',row.id);await remove('investmentAssets',assetId);await load();toast('Yatırım ve yerel hareket geçmişi silindi')};

/* Çoklu para birimi: işlem satırları hesabın kendi tutarını ve TL karşılığını birlikte saklar. */
function accountCurrency(account){return ['TRY','USD','EUR','GBP'].includes(account?.currency)?account.currency:'TRY'}
function accountRateMinor(account){const currency=accountCurrency(account);return currency==='TRY'?100:(Number.isSafeInteger(account?.exchangeRateTryMinor)&&account.exchangeRateTryMinor>0?account.exchangeRateTryMinor:100)}
function nativeToTryMinor(account,nativeMinor){return FinanceCore.convertToTryMinor(nativeMinor,accountRateMinor(account))}
function tryToNativeMinor(account,tryMinor){return FinanceCore.convertFromTryMinor(tryMinor,accountRateMinor(account))}
function postingBaseMinor(posting){return Number.isSafeInteger(posting?.baseAmountMinor)?posting.baseAmountMinor:Number.isSafeInteger(posting?.amountMinor)?posting.amountMinor:Math.round(Number(posting?.amount||0)*100)}
function postingNativeMinor(posting){return Number.isSafeInteger(posting?.amountMinor)?posting.amountMinor:Math.round(Number(posting?.amount||0)*100)}
entryAmount=function(posting){return postingBaseMinor(posting)/100};
function accountNativeBalanceV2(account){const openingMinor=Number.isSafeInteger(account.openingMinor)?account.openingMinor:Math.round(Number(account.opening||0)*100);return state.transactions.filter(transaction=>transaction.date<=dateISO()).reduce((total,transaction)=>total+transaction.postings.filter(posting=>posting.accountId===account.id).reduce((sum,posting)=>sum+postingNativeMinor(posting),0),openingMinor)}
accountBalance=function(account){return nativeToTryMinor(account,accountNativeBalanceV2(account))/100};
function formatAccountNative(account,nativeMinor){return new Intl.NumberFormat('tr-TR',{style:'currency',currency:accountCurrency(account),minimumFractionDigits:2,maximumFractionDigits:2}).format(nativeMinor/100)}
function makeCurrencyPosting(accountId,nativeMinor,baseMinor){return {accountId,amountMinor:nativeMinor,baseAmountMinor:baseMinor,amount:nativeMinor/100}}
function currencyPostings(from,to,sourceMinor){const sourceAccount=state.accounts.find(item=>item.id===from),targetAccount=state.accounts.find(item=>item.id===to),sourceBase=from==='income'?sourceMinor:nativeToTryMinor(sourceAccount,sourceMinor),targetNative=to==='expense'?sourceBase:tryToNativeMinor(targetAccount,sourceBase),rows=[makeCurrencyPosting(from,-(from==='income'?sourceBase:sourceMinor),-sourceBase),makeCurrencyPosting(to,targetNative,sourceBase)];if(rows.reduce((sum,row)=>sum+row.baseAmountMinor,0)!==0)throw new Error('Döviz kaydı dengelenemedi.');return rows}

