const cepFinansDecorateAccountsCurrency=decorateAccounts;decorateAccounts=function(){cepFinansDecorateAccountsCurrency();document.querySelectorAll('.accountCard[data-account-id]').forEach(element=>{const account=state.accounts.find(item=>item.id===element.dataset.accountId);if(!account||accountCurrency(account)==='TRY')return;const amount=element.querySelector('.accountAmount'),native=accountNativeBalanceV2(account),base=accountBalance(account);if(!amount)return;if(account.type==='card'){const limitBase=nativeToTryMinor(account,account.creditLimitMinor||0)/100;amount.textContent=`${formatAccountNative(account,Math.max(0,-native))} borç • ≈ ${money(Math.max(0,-base))} • limit ≈ ${money(limitBase)}`}else amount.textContent=`${formatAccountNative(account,native)} • ≈ ${money(base)}`})};
