async function refreshAccountExchangeRate(accountId){const account=state.accounts.find(item=>item.id===accountId);if(!account||accountCurrency(account)==='TRY'){toast('Bu hesap için döviz kuru gerekmez.');return}if(!navigator.onLine){toast('Kur güncellemesi için internet bağlantısı gerekli.');return}try{const response=await marketFetch(`https://api.frankfurter.dev/v1/latest?base=${encodeURIComponent(accountCurrency(account))}&symbols=TRY`,{referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Kur sağlayıcısı yanıt vermedi.');const data=await response.json(),exchangeRateTryMinor=FinanceCore.marketPriceMinor(data.rates?.TRY);if(!exchangeRateTryMinor)throw new Error('Kur bilgisi bulunamadı.');await put('accounts',{...account,exchangeRateTryMinor,exchangeRateUpdatedAt:new Date().toISOString(),updatedAt:dateISO()});await load();toast(`${account.name} kuru güncellendi`)}catch(error){toast(error.message||'Kur güncellenemedi.')}}
