document.addEventListener('click',event=>{const button=event.target.closest?.('[data-account-refresh-rate]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();refreshAccountExchangeRate(button.dataset.accountRefreshRate)},true);

/* Erken taksit tanıması kart borcunu değiştirmez; yalnızca geleceğe planlanmış gider satırlarını bugüne alır. */
async function earlyRecognizeInstallments(purchaseId){const purchase=state.cardPurchases.find(item=>item.id===purchaseId);if(!purchase)return;const future=(purchase.installments||[]).filter(item=>item.status!=='posted'&&item.dueDate>=dateISO());if(!future.length){toast('Bu alışveriş için ertelenecek taksit kalmadı.');return}const totalMinor=future.reduce((sum,item)=>sum+item.amountMinor,0);if(!confirm(`${purchase.note||'Bu alışveriş'} için kalan ${future.length} taksitin ${money(totalMinor/100)} giderini bugün tanımak istiyor musunuz? Kart borcu değişmez; banka ödemesini ayrıca kaydedin.`))return;const today=dateISO(),nextInstallments=(purchase.installments||[]).map(item=>future.some(row=>row.id===item.id)?{...item,status:'posted',originalDueDate:item.dueDate,dueDate:today,earlyRecognizedAt:new Date().toISOString()}:item);for(const installment of future){const transaction=state.transactions.find(item=>item.id===installment.id);if(transaction)await put('transactions',{...transaction,date:today,planned:false,note:`${transaction.note||purchase.note} (erken tanıma)`,updatedAt:new Date().toISOString()})}await put('cardPurchases',{...purchase,installments:nextInstallments,remainingMinor:0,status:'expense-recognized',updatedAt:new Date().toISOString()});await load();toast('Kalan taksit giderleri bugün tanındı; kart ödemesini ayrıca kaydedin')}
function cardInstallmentTimelineV2(cardId){const card=state.accounts.find(item=>item.id===cardId),purchases=state.cardPurchases.filter(item=>item.cardAccountId===cardId);if(!card)return;const rows=purchases.flatMap(purchase=>(purchase.installments||[]).map((item,index)=>({purchase,date:item.dueDate,amountMinor:item.amountMinor,status:item.status,index}))).filter(item=>item.date>=dateISO()).sort((a,b)=>a.date.localeCompare(b.date)),monthly={};for(const row of rows)monthly[row.date.slice(0,7)]=(monthly[row.date.slice(0,7)]||0)+row.amountMinor;const purchaseControls=purchases.map(purchase=>{const remaining=(purchase.installments||[]).filter(item=>item.status!=='posted'&&item.dueDate>=dateISO()).reduce((sum,item)=>sum+item.amountMinor,0);return remaining?`<div class="budget-row"><b><span>${esc(purchase.note||'Taksitli alışveriş')}</span><span>${money(remaining/100)}</span></b><small>Kalan gider tanıması • Kart borcu bu işlemle değişmez.</small><button type="button" class="textButton" data-installment-early-recognize="${purchase.id}">Kalanı bugün tanı</button></div>`:''}).join('');show(`<h2 class="formTitle">${esc(card.name)} taksit planı</h2><p class="formHint">Kart borcu alışveriş anında oluşur; bu çizelge gider tanıma ve gelecek vade görünümüdür. Banka hesabından ödeme ayrıca “Ödeme yap” ile kaydedilir.</p><h3 class="formTitle" style="font-size:16px">Aylık gelecek yük</h3>${Object.entries(monthly).map(([month,amount])=>`<div class="budget-row"><b><span>${new Date(`${month}-01T12:00`).toLocaleDateString('tr-TR',{month:'long',year:'numeric'})}</span><span>${money(amount/100)}</span></b></div>`).join('')||'<p class="formHint">Gelecek taksit yok.</p>'}<h3 class="formTitle" style="font-size:16px;margin-top:16px">Erken tanıma</h3>${purchaseControls||'<p class="formHint">Erken tanınacak taksit yok.</p>'}<h3 class="formTitle" style="font-size:16px;margin-top:16px">Vade listesi</h3>${rows.slice(0,24).map(row=>`<div class="budget-row"><b><span>${fmtDate(row.date)} • ${esc(row.purchase.note||'Taksitli alışveriş')}</span><span>${money(row.amountMinor/100)}</span></b><small>${row.status==='posted'?'İşlendi':'Planlandı'} • ${row.index+1}/${row.purchase.installments.length}. taksit</small></div>`).join('')||'<p class="formHint">Gösterilecek taksit yok.</p>'}<div class="formActions"><button type="button" onclick="document.getElementById('modal').close()">Kapat</button></div>`,async()=>{})}
