function cardPortfolio(card){const today=dateISO(),cycles=new Map(),payments=[];for(const transaction of state.transactions){const posting=transaction.postings.find(item=>item.accountId===card.id);if(!posting)continue;const amountMinor=Math.round(entryAmount(posting)*100);if(transaction.type==='cardPayment'||amountMinor>0){if(amountMinor>0)payments.push({date:transaction.date,amountMinor});continue}if(amountMinor>=0)continue;if(!card.closingDay)continue;const cycle=FinanceCore.cardCycleWithDueOffset(transaction.date,card.closingDay,10,Boolean(card.closingDayPurchasesNext)),existing=cycles.get(cycle.closingDate)||{closingDate:cycle.closingDate,dueDate:cycle.dueDate,chargeMinor:0,paymentMinor:0};existing.chargeMinor+=Math.abs(amountMinor);cycles.set(cycle.closingDate,existing)}const closed=[...cycles.values()].filter(cycle=>cycle.closingDate<=today).sort((a,b)=>a.closingDate.localeCompare(b.closingDate)),availablePayments=payments.sort((a,b)=>a.date.localeCompare(b.date)).map(item=>({...item}));for(const cycle of closed){for(const payment of availablePayments){if(payment.date<cycle.closingDate||payment.amountMinor<=0)continue;const open=Math.max(0,cycle.chargeMinor-cycle.paymentMinor),allocated=Math.min(open,payment.amountMinor);cycle.paymentMinor+=allocated;payment.amountMinor-=allocated;if(!open)break}}const outstandingMinor=Math.max(0,Math.round(-accountBalance(card)*100)),statementDebt=closed.reduce((sum,cycle)=>sum+Math.max(0,cycle.chargeMinor-cycle.paymentMinor),0),unbilledMinor=[...cycles.values()].filter(cycle=>cycle.closingDate>today).reduce((sum,cycle)=>sum+cycle.chargeMinor,0),futureInstallmentMinor=state.cardPurchases.filter(purchase=>purchase.cardAccountId===card.id).flatMap(purchase=>purchase.installments||[]).filter(item=>item.status!=='posted').reduce((sum,item)=>sum+item.amountMinor,0),overdueMinor=closed.filter(cycle=>cycle.dueDate<today).reduce((sum,cycle)=>sum+Math.max(0,cycle.chargeMinor-cycle.paymentMinor),0),next=closed.filter(cycle=>cycle.chargeMinor>cycle.paymentMinor).sort((a,b)=>a.dueDate.localeCompare(b.dueDate))[0]||null,limitMinor=card.creditLimitMinor||0;return {outstandingMinor,statementDebt,unbilledMinor,futureInstallmentMinor,overdueMinor,next,closed,availableMinor:Math.max(0,limitMinor-outstandingMinor),utilization:limitMinor?Math.round(outstandingMinor/limitMinor*100):0}}
function cardPortfolioForm(cardId){const card=state.accounts.find(item=>item.id===cardId&&item.type==='card');if(!card)return;const model=cardPortfolio(card),rows=[['Toplam kart borcu',model.outstandingMinor],['Kesilmiş, ödenmemiş dönem borcu',model.statementDebt],['Kesilmemiş işlem tutarı',model.unbilledMinor],['Gelecek taksit gideri',model.futureInstallmentMinor],['Kullanılabilir limit',model.availableMinor]],minimum=FinanceCore.minimumCardPayment(model.next?Math.max(0,model.next.chargeMinor-model.next.paymentMinor):model.statementDebt,card.creditLimitMinor||0).amountMinor;show(`<h2 class="formTitle">${esc(card.name)} kart özeti</h2><p class="formHint">Kart borcu, ekstre borcu ve gelecekteki taksit gideri farklı değerlerdir; burada ayrı gösterilir.</p>${rows.map(([label,amount])=>`<div class="budget-row"><b><span>${label}</span><span>${money(amount/100)}</span></b></div>`).join('')}<div class="budget-row"><b><span>Limit kullanımı</span><span>%${model.utilization}</span></b><small>${model.overdueMinor?`Gecikmiş tutar: ${money(model.overdueMinor/100)}`:model.next?`Sonraki son ödeme: ${fmtDate(model.next.dueDate)} • Asgari: ${money(minimum/100)}`:'Kesilmiş açık ekstre yok'}</small></div><h3 class="formTitle" style="font-size:16px;margin-top:16px">Dönem geçmişi</h3>${model.closed.length?model.closed.slice().reverse().slice(0,12).map(cycle=>`<div class="budget-row"><b><span>Kesim ${fmtDate(cycle.closingDate)} • Son ödeme ${fmtDate(cycle.dueDate)}</span><span>${money(Math.max(0,cycle.chargeMinor-cycle.paymentMinor)/100)}</span></b><small>Dönem: ${money(cycle.chargeMinor/100)} • Ödeme: ${money(cycle.paymentMinor/100)} • ${cycle.dueDate<dateISO()&&cycle.chargeMinor>cycle.paymentMinor?'Gecikmiş':'Açık / kapandı'}</small></div>`).join(''):'<div class="budget-row"><b>Henüz kesilmiş dönem yok</b><small>Kesim günü tanımlandığında işlemler otomatik döneme atanır.</small></div>'}<div class="formActions"><button type="button" data-card-payment="${card.id}">Ödeme yap</button><button type="button" onclick="document.getElementById('modal').close()">Kapat</button></div>`,async()=>{})}
