/* Birden fazla depo yazımı gereken finansal olaylar tek IndexedDB işlemiyle kaydedilir. */
function atomicPut(records){const storeNames=[...new Set(records.map(record=>record.store))];return new Promise((resolve,reject)=>{const transaction=db.transaction(storeNames,'readwrite');for(const record of records)transaction.objectStore(record.store).put(record.item);transaction.oncomplete=()=>resolve();transaction.onerror=()=>reject(transaction.error||new Error('Kayıtlar güvenle tamamlanamadı.'));transaction.onabort=()=>reject(transaction.error||new Error('Kayıtlar geri alındı.'))})}
