/* Eşit olmayan kart taksitleri ve finansman farkı: kart borcu bir kez, gider her vadesinde tanınır. */
function parseInstallmentAmounts(value){const parts=String(value||'').split(/[\n;,]+/).map(item=>item.trim()).filter(Boolean);if(!parts.length||parts.length>360)throw new Error('1 ile 360 arasında taksit tutarı girin.');return parts.map(part=>{const minor=FinanceCore.minor(part);if(minor<=0)throw new Error('Her taksit tutarı sıfırdan büyük olmalı.');return minor})}
