function enhancedPostRecurringV3(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring||recurring.active===false)return;const account=state.accounts.find(item=>item.id===recurring.accountId);if(!account||account.archivedAt){toast('Bu plan için aktif bir hesap seçin.');return}const occurrence=recurringOccurrence(recurring);if(recurring.endDate&&occurrence.dueDate>recurring.endDate){toast('Bu planın bitiş tarihi geçti.');return}const income=recurring.direction==='income',amount=(occurrence.amountMinor/100).toFixed(2).replace('.',',');show(`<h2 class="formTitle">Düzenli ${income?'geliri':'ödemeyi'} işle</h2><p class="formHint">Bu işlem gerçek para hareketi oluşturur. Sonraki düzenli vade, özgün takvim kuralına göre ilerletilir.</p><label class="field">Tutar (TL)<input required name="amount" type="text" inputmode="decimal" value="${amount}" ${(recurring.variableAmount||occurrence.amountMinor!==recurring.amountMinor)?'':'readonly'}></label><label class="field">Tarih<input required name="date" type="date" value="${occurrence.dueDate}"></label><div class="formActions"><button>${income?'Geliri kaydet':'Ödemeyi kaydet'}</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const amountMinor=FinanceCore.minor(form.get('amount')),date=FinanceCore.date(form.get('date'));if(amountMinor<=0)throw new Error('Tutar sıfırdan büyük olmalı.');const postings=FinanceCore.ledger(income?[{accountId:recurring.accountId,amountMinor},{accountId:'income',amountMinor:-amountMinor}]:[{accountId:recurring.accountId,amountMinor:-amountMinor},{accountId:'expense',amountMinor}]).map(posting=>({...posting,amount:posting.amountMinor/100})),{nextOccurrenceOverride,...withoutOverride}=recurring,nextRecord=recurringNextRecord(withoutOverride,occurrence.originalDueDate);await atomicPut([{store:'transactions',item:{id:id(),schemaVersion:4,date,note:recurring.name,category:recurring.category,postings,planned:false,recurringId,recurringOriginalDueDate:occurrence.originalDueDate}},{store:'recurringTransactions',item:nextRecord}]);await load();toast(income?'Düzenli gelir işlendi':'Düzenli ödeme işlendi')}catch(error){toast(error.message||'Düzenli kayıt işlenemedi.')}})}
async function skipRecurringV4(recurringId){const recurring=state.recurring.find(item=>item.id===recurringId);if(!recurring||recurring.active===false)return;const occurrence=recurringOccurrence(recurring);if(!confirm(`${recurring.name} için ${fmtDate(occurrence.dueDate)} vadesi atlanacak. Devam edilsin mi?`))return;const {nextOccurrenceOverride,...withoutOverride}=recurring;await put('recurringTransactions',{...recurringNextRecord(withoutOverride,occurrence.originalDueDate),lastSkippedDate:occurrence.originalDueDate});await load();toast('Vade atlandı; sonraki tarih ilerletildi')}
async function postAutomaticRecurringOnOpen(){const today=dateISO(),records=[];for(const recurring of state.recurring.filter(item=>item.active!==false&&item.postingPolicy==='auto')){let current=recurring;for(let guard=0;guard<120&&current.active!==false&&current.nextDueDate<=today;guard++){if(current.endDate&&current.nextDueDate>current.endDate){current={...current,active:false,updatedAt:new Date().toISOString()};records.push({store:'recurringTransactions',item:current});break}const originalDueDate=current.nextDueDate,exists=state.transactions.some(transaction=>transaction.recurringId===current.id&&transaction.recurringOriginalDueDate===originalDueDate);if(!exists){const amountMinor=current.amountMinor,postings=FinanceCore.ledger(current.direction==='income'?[{accountId:current.accountId,amountMinor},{accountId:'income',amountMinor:-amountMinor}]:[{accountId:current.accountId,amountMinor:-amountMinor},{accountId:'expense',amountMinor}]).map(posting=>({...posting,amount:posting.amountMinor/100}));records.push({store:'transactions',item:{id:id(),schemaVersion:4,date:originalDueDate,note:current.name,category:current.category,postings,planned:false,recurringId:current.id,recurringOriginalDueDate:originalDueDate,autoPostedAt:new Date().toISOString()}})}current=recurringNextRecord(current,originalDueDate);records.push({store:'recurringTransactions',item:current})}}if(records.length)await atomicPut(records);return records.length}
const cepFinansLoadWithAutomaticRecurring=load;let automaticRecurringBusy=false;load=async function(){await cepFinansLoadWithAutomaticRecurring();if(automaticRecurringBusy||!state.recurring?.some(item=>item.active!==false&&item.postingPolicy==='auto'))return;automaticRecurringBusy=true;try{const count=await postAutomaticRecurringOnOpen();if(count)await cepFinansLoadWithAutomaticRecurring()}catch(error){console.warn('Otomatik düzenli kayıt işlenemedi.',error)}finally{automaticRecurringBusy=false}};
const cepFinansCalendarWithEndDates=calendarEvents;calendarEvents=function(month){return cepFinansCalendarWithEndDates(month).filter(event=>{if(event.action!=='recurring')return true;const recurring=state.recurring.find(item=>item.id===event.key);return !recurring?.endDate||event.date<=recurring.endDate})};
