function recurringCashByMonthV3(monthKey,cashAccounts){let income=0,expense=0;for(const recurring of state.recurring.filter(item=>item.active!==false)){let originalDue=recurring.nextDueDate;for(let guard=0;guard<800&&originalDue.slice(0,7)<=monthKey;guard++){if(recurring.endDate&&originalDue>recurring.endDate)break;const occurrence=originalDue===recurring.nextDueDate?recurringOccurrence(recurring):{dueDate:originalDue,amountMinor:recurring.amountMinor};if((!recurring.endDate||occurrence.dueDate<=recurring.endDate)&&occurrence.dueDate.slice(0,7)===monthKey&&cashAccounts.some(account=>account.id===recurring.accountId)){if(recurring.direction==='income')income+=occurrence.amountMinor/100;else expense+=occurrence.amountMinor/100}originalDue=nextRecurringDate(recurring,originalDue)}}for(const debt of [...state.debts,...state.loans].filter(item=>item.active!==false)){for(let payment=0;payment<Math.min(600,Number(item.remainingInstallments)||0);payment++){const due=FinanceCore.addMonths(item.nextDueDate,payment);if(due.slice(0,7)===monthKey){if(item.direction==='incoming')income+=item.monthlyPaymentMinor/100;else expense+=item.monthlyPaymentMinor/100}if(due.slice(0,7)>monthKey)break}}return {income,expense}}
