function setupTransactionGrouping(){const filters=$('#txFilters');if(!filters||$('#txGroupingFilter'))return;const select=document.createElement('select');select.id='txGroupingFilter';select.setAttribute('aria-label','Hareket gruplama');select.style.cssText='margin-top:8px;padding:8px;border-radius:10px;border:1px solid #ffffff18;background:#ffffff0d;color:inherit';select.innerHTML='<option value="date">Tarihe göre grupla</option><option value="category">Kategoriye göre grupla</option><option value="none">Gruplama yok</option>';select.value=transactionGrouping;select.onchange=event=>{transactionGrouping=event.target.value;render()};filters.append(select)}
