function budgetModeForm(){const current=budgetModeSetting();show(`<h2 class="formTitle">Bütçe modu</h2><p class="formHint">Sıfır-tabanlı görünüm, bu ayın gerçekleşen gelirinden bütçelere ayrılmış tutarı gösterir. Bu ayar gerçek para veya geçmiş hareket oluşturmaz.</p><label class="field">Sıfır-tabanlı planlama kullan<input name="zeroBased" type="checkbox" ${current.zeroBased?'checked':''}></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{await put('appSettings',{...current,zeroBased:form.get('zeroBased')==='on',updatedAt:new Date().toISOString()});await load();toast('Bütçe modu kaydedildi')}catch(error){toast(error.message||'Bütçe modu kaydedilemedi.')}})}
function budgetAllocationForm(){const budgets=state.budgets.filter(item=>item.active!==false);if(!budgets.length){toast('Önce sınıflandırmak istediğiniz bir bütçe oluşturun.');return}show(`<h2 class="formTitle">Bütçe tahsisini sınıflandır</h2><p class="formHint">Sınıflama raporlama ve planlama içindir; mevcut limit veya geçmiş harcama değişmez.</p><label class="field">Bütçe<select name="budgetId">${budgets.map(item=>`<option value="${item.id}">${esc(budgetTitle(item))} • ${money(item.limitMinor/100)}</option>`).join('')}</select></label><label class="field">Tahsis türü<select name="allocationType"><option value="variable">Değişken gider</option><option value="fixed">Sabit gider</option><option value="savings">Birikim tahsisi</option><option value="sinking">Yıllık gider fonu</option></select></label><label class="field">Yıllık fon hedefi (TL, yalnızca yıllık fon için)<input name="annualTarget" type="text" inputmode="decimal" value="0,00"></label><label class="field">Hedef ay (1–12)<input name="targetMonth" type="number" min="1" max="12" inputmode="numeric" value="12"></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const budget=state.budgets.find(item=>item.id===form.get('budgetId')),allocationType=String(form.get('allocationType')),annualTargetMinor=FinanceCore.minor(form.get('annualTarget')||0),targetMonth=Math.max(1,Math.min(12,Number(form.get('targetMonth'))||12));if(!budget||annualTargetMinor<0)throw new Error('Bütçe bilgisi geçersiz.');await put('budgets',{...budget,schemaVersion:4,allocationType,annualTargetMinor:allocationType==='sinking'?annualTargetMinor:0,targetMonth:allocationType==='sinking'?targetMonth:null,updatedAt:new Date().toISOString()});await load();toast('Bütçe tahsisi kaydedildi')}catch(error){toast(error.message||'Bütçe tahsisi kaydedilemedi.')}})}
