isLiquidAccount=function(account){return Boolean(account)&&['bank','cash','savings','foreign','wallet','prepaid'].includes(account.type)};

/* Kredi/borç için kullanıcı tanımlı değişken vade takvimi, tahmin ve takvimden aynı kaynaktan okunur. */
function parseDebtSchedule(value,remainingMinor){const rows=String(value||'').split(/\r?\n/).map(row=>row.trim()).filter(Boolean).map((row,index)=>{const [dateRaw,amountRaw]=row.split(/[;,]/).map(item=>item?.trim());try{return {date:FinanceCore.date(dateRaw||''),amountMinor:FinanceCore.minor(amountRaw||'')}}catch(error){throw new Error(`${index+1}. vade satırı geçersiz.`)}});return FinanceCore.debtPaymentSchedule(rows,remainingMinor)}
function debtScheduleForm(debtId){const inLoans=state.loans.some(item=>item.id===debtId),store=inLoans?'loans':'debts',debt=(inLoans?state.loans:state.debts).find(item=>item.id===debtId);if(!debt||debt.active===false)return;const initial=(debt.paymentSchedule||[]).map(row=>`${row.date}; ${(row.amountMinor/100).toFixed(2).replace('.',',')}`).join('\n');show(`<h2 class="formTitle">Değişken vade takvimi</h2><p class="formHint">Her satıra “YYYY-AA-GG; tutar” yazın. Bu takvim 12 aylık nakit akışında standart aylık tutarın yerine kullanılır. Plan uzlaştırıldıkça kalan anapara ayrıca güncellenir.</p><label class="field">Vade satırları<textarea required name="schedule" rows="8" inputmode="decimal" placeholder="2027-01-15; 5.000,00\n2027-02-15; 7.500,00">${esc(initial)}</textarea></label><div class="formActions"><button>Takvimi kaydet</button><button type="button" data-debt-schedule-clear="${debt.id}">Standart aylık plana dön</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const paymentSchedule=parseDebtSchedule(form.get('schedule'),debt.remainingMinor);await put(store,{...debt,paymentSchedule,scheduleMode:'manual',updatedAt:new Date().toISOString()});await load();toast('Değişken vade takvimi kaydedildi')}catch(error){toast(error.message||'Vade takvimi kaydedilemedi.')}})}
async function clearDebtSchedule(debtId){const inLoans=state.loans.some(item=>item.id===debtId),store=inLoans?'loans':'debts',debt=(inLoans?state.loans:state.debts).find(item=>item.id===debtId);if(!debt||!confirm(`${debt.name} için standart aylık plana dönülsün mü?`))return;const {paymentSchedule,scheduleMode,...record}=debt;await put(store,{...record,updatedAt:new Date().toISOString()});await load();toast('Standart aylık plan geri yüklendi')}
