const cepFinansRenderWithDebtSchedules=render;render=function(){cepFinansRenderWithDebtSchedules();renderDebtScheduleControls()};document.addEventListener('click',event=>{const edit=event.target.closest?.('[data-debt-schedule]'),clear=event.target.closest?.('[data-debt-schedule-clear]');if(edit){event.preventDefault();event.stopImmediatePropagation();debtScheduleForm(edit.dataset.debtSchedule)}if(clear){event.preventDefault();event.stopImmediatePropagation();clearDebtSchedule(clear.dataset.debtScheduleClear)}},true);
