/* Ana ekrandaki eğri ve gün etiketi, örnek görsel yerine cihazdaki son 30 günün gerçek nakit akışından üretilir. */
function renderDashboardDataVisuals(){const dashboard=$('#dashboard'),spark=dashboard?.querySelector('.spark svg'),dayChip=dashboard?.querySelector('.day-chip'),growth=dashboard?.querySelector('.growth');if(dayChip)dayChip.textContent=`Ayın ${Number(dateISO().slice(-2))}'i`;const liquid=state.accounts.filter(account=>isLiquidAccount(account)&&!account.archivedAt),days=[];for(let offset=29;offset>=0;offset--){const day=FinanceCore.addDays(dateISO(),-offset),delta=state.transactions.filter(transaction=>!transaction.planned&&transaction.date===day).reduce((sum,transaction)=>sum+transaction.postings.filter(posting=>liquid.some(account=>account.id===posting.accountId)).reduce((inner,posting)=>inner+entryAmount(posting),0),0);days.push({day,delta})}let cumulative=0,values=days.map(row=>cumulative+=row.delta),minimum=Math.min(0,...values),maximum=Math.max(0,...values),range=Math.max(1,maximum-minimum),points=values.map((value,index)=>`${(index/(values.length-1)*296+2).toFixed(1)},${(54-(value-minimum)/range*42).toFixed(1)}`),line=`M${points.join(' L')}`,area=`${line} L298,64 L2,64 Z`;if(spark)spark.innerHTML=`<defs><linearGradient id="dashboard-glow" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#55ee71" stop-opacity=".35"/><stop offset="1" stop-color="#55ee71" stop-opacity="0"/></linearGradient></defs><path d="${area}" fill="url(#dashboard-glow)"/><path d="${line}" fill="none" stroke="#55ee71" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${points.at(-1).split(',')[0]}" cy="${points.at(-1).split(',')[1]}" r="4" fill="#55ee71"/>`;const monthly=days.reduce((sum,row)=>sum+row.delta,0);if(growth){growth.innerHTML=`<span>${monthly>=0?'↗':'↘'}</span> Son 30 gün: ${monthly>=0?'+':''}${money(monthly)}`;growth.style.color=monthly<0?'var(--coral)':'';growth.style.background=monthly<0?'#563d40':''}}
