/* Gram altın için birincil kaynak kesintiye uğrarsa, ons altın vadeli fiyatı ve
   USD/TRY kuru yerelde grama çevrilir. Bu yalnızca güncelleme düğmesine basılınca
   çalışır; fiyatın türetildiği kaynak ayrıca kayda yazılır. */
async function fallbackGramGoldQuote(){const source='https://query1.finance.yahoo.com/v8/finance/chart/GC=F?range=1d&interval=1d',response=await marketFetch(`https://proxy.cors.dev/${source}`,{credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Alternatif altın fiyat sağlayıcısı yanıt vermedi.');const data=await response.json(),priceUsdPerOunce=data.chart?.result?.[0]?.meta?.regularMarketPrice;if(!Number.isFinite(priceUsdPerOunce)||priceUsdPerOunce<=0)throw new Error('Alternatif altın fiyatı bulunamadı.');const usdTry=await fetchTryExchangeRate('USD'),tryPerGram=priceUsdPerOunce*(usdTry.rateMinor/100)/31.1034768,priceMinor=FinanceCore.marketPriceMinor(tryPerGram);if(priceMinor<=0)throw new Error('Alternatif gram altın fiyatı geçersiz.');return {priceMinor,source:`Yahoo Finance GC=F + ${usdTry.source}`}}
const cepFinansRefreshInvestmentWithGoldFallback=refreshInvestment;refreshInvestment=async function(asset){if(asset.type!=='gold')return cepFinansRefreshInvestmentWithGoldFallback(asset);try{return await cepFinansRefreshInvestmentWithGoldFallback(asset)}catch(primaryError){try{const quote=await fallbackGramGoldQuote();await put('assetValuations',{id:id(),assetId:asset.id,priceMinor:quote.priceMinor,date:dateISO(),fetchedAt:new Date().toISOString(),source:quote.source});await put('investmentAssets',{...asset,currentPriceMinor:quote.priceMinor,currentPriceDate:dateISO(),priceSource:quote.source,updatedAt:dateISO()})}catch(fallbackError){throw new Error(fallbackError.message||primaryError.message||'Altın fiyatı alınamadı.')}}};

/* Tahminde ilk kesilmiş dönem gerçek açık ekstre borcuyla, sonraki dönemler ise
   aynı kartın bilinen alışverişlerinin kesim/son ödeme kuralıyla gösterilir. */
function cardPaymentForecastMinor(card,monthKey){if(!card?.closingDay)return 0;const preview=cardStatementPreview(card);if(preview?.dueDate?.startsWith(monthKey))return Math.max(0,preview.outstandingMinor||0);let total=0;for(const transaction of state.transactions.filter(item=>!item.planned)){const posting=transaction.postings.find(item=>item.accountId===card.id);if(!posting||transaction.type==='cardPayment')continue;const amountMinor=Math.round(entryAmount(posting)*100);if(amountMinor>=0&&!transaction.partialRefundOf&&!transaction.reversalOf)continue;const cycle=FinanceCore.cardCycleWithDueOffset(transaction.date,card.closingDay,10,Boolean(card.closingDayPurchasesNext));if(cycle.dueDate.startsWith(monthKey))total-=amountMinor}return Math.max(0,total)}
function forecastModelV3(){const cashAccounts=state.accounts.filter(account=>isLiquidAccount(account)&&!account.archivedAt&&account.includeInTotals!==false),scenario=currentForecastScenario(),monthlyScenarioIncome=(scenario?.monthlyIncomeMinor||0)/100,monthlyScenarioExpense=(scenario?.monthlyExpenseMinor||0)/100,monthlyScenarioSavings=(scenario?.monthlySavingsMinor||0)/100,oneTimeExpense=(scenario?.oneTimeExpenseMinor||0)/100;let closing=cashAccounts.reduce((total,account)=>total+accountBalance(account),0),rows=[];for(let index=0;index<12;index++){const monthStart=FinanceCore.addMonths(`${dateISO().slice(0,8)}01`,index),monthKey=monthStart.slice(0,7),opening=closing,planned={income:0,expense:0};for(const transaction of state.transactions.filter(item=>item.planned&&item.date>=dateISO()&&item.date.startsWith(monthKey))){for(const posting of transaction.postings.filter(item=>cashAccounts.some(account=>account.id===item.accountId))){if(entryAmount(posting)>=0)planned.income+=entryAmount(posting);else planned.expense+=Math.abs(entryAmount(posting))}}const recurring=recurringCashByMonth(monthKey,cashAccounts),cardPayments=state.accounts.filter(account=>account.type==='card'&&!account.archivedAt).reduce((total,account)=>total+cardPaymentForecastMinor(account,monthKey)/100,0),income=planned.income+recurring.income+monthlyScenarioIncome,expense=planned.expense+recurring.expense+cardPayments+monthlyScenarioExpense+(index===0?oneTimeExpense:0),goalSavings=suggestedGoalSavingsMinor(monthKey)/100+monthlyScenarioSavings;closing=opening+income-expense;rows.push({monthStart,monthKey,opening,income,expense,cardPayments,recurringExpense:recurring.expense,plannedExpense:planned.expense,goalSavings,availableDiscretionary:closing-goalSavings,closing})}return rows}
forecastModel=forecastModelV3;

/* Plan raporunda düzenli gelir, gider ve abonelikler birbirine karışmaz.
   Aylık eşdeğer, farklı tekrar sıklıklarını karşılaştırılabilir kılar. */
function recurringMonthlyEquivalentMinor(record){const amount=Number(record?.amountMinor||0),frequency=record?.frequency,interval=Math.max(1,Number(record?.customIntervalDays)||1);if(!Number.isSafeInteger(amount)||amount<0)return 0;const factor={daily:30.4375,weekly:52.142857/12,biweekly:26.071429/12,monthly:1,quarterly:1/3,semiannual:1/6,yearly:1/12,custom:30.4375/interval}[frequency]??1;return Math.round(amount*factor)}
