/* Senaryo seçildiğinde mevcut plana göre 12 ay sonu tahmini nakit farkı açıkça
   gösterilir; hedef tahsisi nakit hareketi olmadığı için bu farkı değiştirmez. */
function scenarioTwelveMonthCashDifferenceMinor(scenario){if(!scenario)return 0;return ((scenario.monthlyIncomeMinor||0)-(scenario.monthlyExpenseMinor||0))*12-(scenario.oneTimeExpenseMinor||0)}
