/* KKDF/BSMV gibi krediye özgü vergiler varsayılan sıfırla başlar; kullanıcı
   oranı ve etkin tarihi girer. Vergi, anaparayı değil ilgili vadenin nakit
   yükünü artırır ve geçmiş oranı değiştirmez. */
function safeTaxBps(value){const rate=Number(value);return Number.isSafeInteger(rate)&&rate>=0&&rate<=1000000?rate:0}
