function showAmortizationWithTaxes(debtId){const debt=[...state.debts,...state.loans].find(item=>item.id===debtId);if(!debt)return;try{const rows=FinanceCore.variableAmortization(debt.remainingMinor,debt.monthlyPaymentMinor,amortizationBaseRate(debt),rateChangesForAmortization(debt),Math.max(1,debt.remainingInstallments||600)),preview=rows.slice(0,12).map(row=>{const due=FinanceCore.addMonths(debt.nextDueDate,row.period-1),tax=taxConfigForDebtDate(debt,due),taxMinor=debtTaxMinor(row.interestMinor,tax),cashMinor=row.paymentMinor+taxMinor;return `<div class="budget-row"><b><span>${fmtDate(due)} • ${row.period}. vade</span><span>${money(cashMinor/100)}</span></b><small>Faiz: ${money(row.interestMinor/100)} • Anapara: ${money(row.principalMinor/100)} • Vergi: ${money(taxMinor/100)} (KKDF %${(tax.kkdfBps/100).toLocaleString('tr-TR',{minimumFractionDigits:2})}, BSMV %${(tax.bsmvBps/100).toLocaleString('tr-TR',{minimumFractionDigits:2})}) • Kalan: ${money(row.remainingMinor/100)}</small></div>`}).join('');show(`<h2 class="formTitle">${esc(debt.name)} amortismanı</h2><p class="formHint">Vergi/masraf satırı, sözleşmeye göre kullanıcı tarafından girilen etkin oranlardan hesaplanır; anapara bakiyesine eklenmez.</p>${preview}${rows.length>12?'<p class="formHint">İlk 12 vade gösteriliyor.</p>':''}<div class="formActions"><button type="button" onclick="document.getElementById('modal').close()">Kapat</button></div>`,async()=>{})}catch(error){toast(error.message||'Amortisman hesaplanamadı.')}}
