/* Toplu işlemde taksit grubunun yalnızca bir satırını silmek veya farklı
   kategorilemek defteri parçalayabilir. Seçim bu nedenle otomatik olarak tüm
   bağlı vadelere genişler; ekler ve kart alışverişi aynı IndexedDB işleminde
   silinir. */
function expandedBulkTransactionIds(){const ids=new Set(bulkSelection);for(const transaction of state.transactions){if(ids.has(transaction.id)&&transaction.installmentGroup)for(const related of state.transactions.filter(item=>item.installmentGroup===transaction.installmentGroup))ids.add(related.id)}return ids}
function deleteBulkTransactionsAtomically(ids){const attachmentIds=state.attachments.filter(item=>ids.has(item.transactionId)).map(item=>item.id),purchaseIds=[...new Set(state.transactions.filter(item=>ids.has(item.id)&&item.installmentGroup&&state.cardPurchases.some(purchase=>purchase.id===item.installmentGroup)).map(item=>item.installmentGroup))],stores=['transactions','attachments',...(purchaseIds.length?['cardPurchases']:[])];return new Promise((resolve,reject)=>{let operation;try{operation=db.transaction(stores,'readwrite');for(const transactionId of ids)operation.objectStore('transactions').delete(transactionId);for(const attachmentId of attachmentIds)operation.objectStore('attachments').delete(attachmentId);for(const purchaseId of purchaseIds)operation.objectStore('cardPurchases').delete(purchaseId);operation.oncomplete=resolve;operation.onerror=()=>reject(operation.error||new Error('Toplu silme tamamlanamadı.'));operation.onabort=()=>reject(operation.error||new Error('Toplu silme geri alındı.'))}catch(error){reject(error)}})}
function bulkCategoryForm(){const ids=expandedBulkTransactionIds();if(!ids.size)return;show(`<h2 class="formTitle">Toplu kategorile</h2><p class="formHint">${ids.size} hareketin yalnızca kategori bilgisi değişir; tutarlar ve hesaplar korunur. Seçili bir taksitin tüm bağlı vadeleri birlikte güncellenir.</p><label class="field">Yeni kategori<select name="category">${availableCategories().map(name=>`<option>${esc(name)}</option>`).join('')}</select></label><div class="formActions"><button>Kaydet</button><button type="button" onclick="document.getElementById('modal').close()">Vazgeç</button></div>`,async form=>{try{const category=String(form.get('category')||'Diğer'),records=state.transactions.filter(item=>ids.has(item.id)).map(transaction=>({store:'transactions',item:{...transaction,category,subcategory:'',updatedAt:new Date().toISOString()}}));await atomicPut(records);bulkSelection.clear();await load();toast('Seçili hareketler kategorilendi')}catch(error){toast(error.message||'Toplu kategorileme kaydedilemedi.')}})}
