/* Borç azaltım raporu, nakit akışıyla karıştırılmadan yalnızca anapara
   değişimini gösterir. Gelecek satırlar plan niteliğindedir; gerçek ödeme
   yapıldığında kalan anaparadan yeniden türetilir. */
function debtPrincipalReductionForecastMinor(debt,months=12){const limit=FinanceCore.addMonths(dateISO(),months),scheduled=Array.isArray(debt.paymentSchedule)?debt.paymentSchedule:[];if(scheduled.length)return scheduled.filter(row=>row.date>=dateISO()&&row.date<limit).reduce((sum,row)=>sum+Math.max(0,Number(row.amountMinor||0)),0);try{const rows=FinanceCore.variableAmortization(debt.remainingMinor,debt.monthlyPaymentMinor,amortizationBaseRate(debt),rateChangesForAmortization(debt),Math.min(600,Number(debt.remainingInstallments)||0));return rows.reduce((sum,row)=>{const due=FinanceCore.addMonths(debt.nextDueDate,row.period-1);return due>=dateISO()&&due<limit?sum+row.principalMinor:sum},0)}catch(error){return 0}}
function renderDebtReductionReport(){const analytics=$('#analytics');if(!analytics)return;let card=$('#debtReductionReportCard');if(!card){card=document.createElement('article');card.id='debtReductionReportCard';card.className='glass-card';card.innerHTML='<div class="eyebrow">BORÇ AZALTIMI</div><h2>Anapara planı</h2><p id="debtReductionSummary" class="formHint"></p><div id="debtReductionRows" class="budget-list"></div>';analytics.append(card)}const plans=[...state.debts,...state.loans].filter(item=>item.direction!=='incoming'&&item.active!==false),rows=plans.map(debt=>{const original=Math.max(0,Number(debt.principalMinor||debt.remainingMinor||0)),remaining=Math.max(0,Number(debt.remainingMinor||0)),reduced=Math.max(0,original-remaining),nextYear=Math.min(remaining,debtPrincipalReductionForecastMinor(debt));return {debt,original,remaining,reduced,nextYear}}),totalRemaining=rows.reduce((sum,row)=>sum+row.remaining,0),totalNextYear=rows.reduce((sum,row)=>sum+row.nextYear,0);$('#debtReductionSummary').textContent=rows.length?`Kalan anapara: ${money(totalRemaining/100)} • Önümüzdeki 12 ay planlı anapara azalması: ${money(totalNextYear/100)}. Faiz, vergi ve masraflar bu azaltım tutarına dahil değildir.`:'Etkin kredi veya borç planı yok.';$('#debtReductionRows').innerHTML=rows.length?rows.map(row=>`<div class="budget-row"><b><span>${esc(row.debt.name)}</span><span>${money(row.remaining/100)}</span></b><small>Başlangıç: ${money(row.original/100)} • Azaltılan: ${money(row.reduced/100)} • 12 ay planlı anapara: ${money(row.nextYear/100)} • Sonraki vade: ${fmtDate(row.debt.nextDueDate)}</small></div>`).join(''):'<div class="budget-row"><b>Gösterilecek borç azaltımı yok</b><small>Etkin bir kredi veya borç planı eklediğinizde burada görünür.</small></div>'}
const cepFinansRenderWithDebtReductionReport=render;render=function(){cepFinansRenderWithDebtReductionReport();renderDebtReductionReport()};

