/* Değerleme geçmişi, kullanıcının daha önce yerelde saklanmış fiyatlarından
   oluşur; geçmiş performans için yeni bir ağ isteği veya tahmin yapılmaz. */
function investmentPerformanceHistory(assetId){const asset=state.investments.find(item=>item.id===assetId);if(!asset)return;const records=state.assetValuations.filter(item=>item.assetId===asset.id&&Number.isSafeInteger(item.priceMinor)).slice().sort((left,right)=>String(right.date||'').localeCompare(String(left.date||''))||String(right.fetchedAt||'').localeCompare(String(left.fetchedAt||''))),costValue=investmentValueMinor(asset,asset.costPriceMinor)||0,latest=records[0],latestValue=latest?investmentValueMinor(asset,latest.priceMinor):null,profit=latestValue===null?null:latestValue-costValue,first=records.at(-1),movement=latest&&first&&first.priceMinor?Math.round((latest.priceMinor-first.priceMinor)/first.priceMinor*100):null;show(`<h2 class="formTitle">${esc(asset.name)} fiyat geçmişi</h2><p class="formHint">Bu liste yalnızca bu cihazda, “Fiyatları güncelle” veya elle değerleme sırasında kaydedilmiş değerlerden oluşur.</p><div class="budget-row"><b><span>Alış maliyeti</span><span>${money(costValue/100)}</span></b>${latestValue===null?'<small>Henüz yerel değerleme yok.</small>':`<small>Güncel değer: ${money(latestValue/100)} • Kâr / zarar: ${profit>=0?'+':''}${money(profit/100)}${movement===null?'':` • İlk kayda göre fiyat: ${movement>=0?'+':''}%${movement}`}</small>`}</div><div class="budget-list" style="margin-top:12px">${records.length?records.slice(0,36).map(record=>{const value=investmentValueMinor(asset,record.priceMinor);return `<div class="budget-row"><b><span>${fmtDate(record.date)}</span><span>${money(record.priceMinor/100)}</span></b><small>Toplam değer: ${money((value||0)/100)} • Kaynak: ${esc(record.source||'Yerel değerleme')}</small></div>`}).join(''):'<div class="budget-row"><b>Değerleme geçmişi yok</b><small>Yatırım ekranından fiyatı güncellediğinizde burada görünür.</small></div>'}</div><div class="formActions"><button type="button" onclick="document.getElementById('modal').close()">Kapat</button></div>`,async()=>{})}
