/* Hisse ve ETF sembollerinde Stooq doğrudan denenir. Sembolün ülke eki para
   birimini açıkça belirliyorsa TL karşılığı yerelde hesaplanır; aksi durumda
   mevcut Yahoo akışı devreye girer. Bu istek yalnızca sembolü taşır. */
function stooqQuoteCurrency(symbol){const suffix=String(symbol||'').trim().toUpperCase().split('.').at(-1);return ({US:'USD',UK:'GBP',DE:'EUR'})[suffix]||null}
async function fetchStooqInvestmentQuote(asset){const symbol=String(asset.symbol||'').trim().toLowerCase();if(!/^[a-z0-9._-]{2,30}$/.test(symbol))throw new Error('Stooq sembolü geçersiz.');const currency=stooqQuoteCurrency(symbol);if(!currency)throw new Error('Stooq için para birimi belirsiz.');const response=await marketFetch(`https://stooq.com/q/l/?s=${encodeURIComponent(symbol)}&f=sd2t2ohlcv&h&e=csv`,{referrerPolicy:'no-referrer'});if(!response.ok)throw new Error('Stooq fiyat sağlayıcısı yanıt vermedi.');const lines=(await response.text()).trim().split(/\r?\n/);if(lines.length<2)throw new Error('Stooq fiyatı bulunamadı.');const cells=lines.at(-1).split(',').map(value=>value.trim()),close=Number(cells[6]);if(!Number.isFinite(close)||close<=0)throw new Error('Stooq kapanış fiyatı geçersiz.');let priceMinor=FinanceCore.marketPriceMinor(close);if(currency!=='TRY'){const quote=await fetchTryExchangeRate(currency);priceMinor=Number((BigInt(priceMinor)*BigInt(quote.rateMinor))/100n)}if(!Number.isSafeInteger(priceMinor)||priceMinor<=0)throw new Error('Stooq TL fiyatı geçersiz.');return {priceMinor,source:`Stooq${currency==='TRY'?'':` + ${currency}/TRY`}`}}
const cepFinansRefreshInvestmentWithStooqFallback=refreshInvestment;refreshInvestment=async function(asset){if(!['stock','etf'].includes(asset.type))return cepFinansRefreshInvestmentWithStooqFallback(asset);try{const quote=await fetchStooqInvestmentQuote(asset);await put('assetValuations',{id:id(),assetId:asset.id,priceMinor:quote.priceMinor,date:dateISO(),fetchedAt:new Date().toISOString(),source:quote.source});await put('investmentAssets',{...asset,currentPriceMinor:quote.priceMinor,currentPriceDate:dateISO(),priceSource:quote.source,updatedAt:dateISO()})}catch(error){return cepFinansRefreshInvestmentWithStooqFallback(asset)}};

/* Yedek oluşturulduktan sonra yalnızca tarih, sürüm ve kayıt sayısı yerelde
   hatırlanır. Parola, şifreli içerik ve indirilen dosya hiçbir zaman saklanmaz. */
async function backupWithLocalMetadata(){try{const snapshot={version:4,createdAt:new Date().toISOString()};for(const storeName of BACKUP_STORES)snapshot[storeName]=storeName==='accounts'?state.accounts:storeName==='transactions'?state.transactions:storeName==='attachments'?await attachmentBackupRows():await all(storeName);const recordCount=BACKUP_STORES.reduce((total,storeName)=>total+snapshot[storeName].length,0);if(!recordCount){toast('Yedeklenecek kayıt yok.');return}const pass=prompt('Yedek parolasını belirleyin. Bu parola olmadan geri yüklenemez.');if(!pass)return;const repeat=prompt('Parolayı tekrar girin.');if(pass!==repeat){toast('Parolalar eşleşmiyor.');return}const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(pass,salt),plain=new TextEncoder().encode(JSON.stringify(snapshot)),encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain),data={format:'cep-finans-backup',version:4,kdf:'PBKDF2-SHA-256',iterations:250000,salt:b64(salt),iv:b64(iv),ciphertext:b64(new Uint8Array(encrypted))};download(JSON.stringify(data),`cep-finans-yedek-${dateISO()}.cepfinans`);await put('appSettings',{id:'backup-metadata',kind:'backupMetadata',lastCreatedAt:snapshot.createdAt,recordCount,formatVersion:4});await load();toast('Şifreli yedek indirildi')}catch(error){toast(error.message||'Yedek oluşturulamadı.')}}
backup=backupWithLocalMetadata;if($('#backupBtn'))$('#backupBtn').onclick=backup;
function backupMetadata(){return (state.settings||[]).find(item=>item.id==='backup-metadata')||null}
const cepFinansStorageSafetyCard=renderStorageSafetyCard;renderStorageSafetyCard=function(){cepFinansStorageSafetyCard();const detail=$('#storageSafetyCard p'),metadata=backupMetadata();if(detail&&metadata?.lastCreatedAt){const when=new Date(metadata.lastCreatedAt).toLocaleString('tr-TR');detail.textContent=`Son şifreli yedek: ${when} (${metadata.recordCount||0} kayıt). Veriler bu iPhone’daki tarayıcı deposunda kalır; Safari web sitesi verileri silinirse kayıtlar da silinebilir.`}};
